INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gripskids---deutsch-germany', 'NDS', 'GripsKids - Deutsch (Germany)', '2008', 'Educational', 'Tivola', '1', 'Kids', 'Educational and language.', 'Improve your German language skills through fun games.', 'An educational trainer for German spelling and grammar.', 'GripsKids: Deutsch on NDS makes learning fun for primary school students. Through interactive drills and games, children can practice their German skills and prepare for higher school levels in an engaging way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gripskids---mathematik-europe-enfrdeit', 'NDS', 'GripsKids - Mathematik (Europe) (En,Fr,De,It)', '2009', 'Educational', 'Tivola', '1', 'Kids', 'Educational and mathematics.', 'Solve math problems to sharpen your mental calculation.', 'A comprehensive math trainer for students and kids.', 'GripsKids: Mathematik offers a variety of numerical challenges on NDS. From basic arithmetic to geometry, use the touch screen to solve problems and track your progress in this effective educational tool.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gripskids---sachkunde-germany', 'NDS', 'GripsKids - Sachkunde (Germany)', '2008', 'Educational', 'Tivola', '1', 'Kids', 'Educational and general knowledge.', 'Learn about nature, science, and the world around you.', 'An educational game focused on general school subjects.', 'GripsKids: Sachkunde on NDS encourages curiosity. Explore topics like biology, history, and geography through interactive lessons and quizzes designed to help German students succeed in their early school years.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('groovy-chick---my-fashion-world-europe-endeesit', 'NDS', 'Groovy Chick - My Fashion World (Europe) (En,De,Es,It)', '2009', 'Simulation', 'Funbox Media', '1', 'Fashion', 'Fashion and lifestyle.', 'Design clothes and manage your social life in a groovy world.', 'A girl-centric fashion game based on the Groovy Chick brand.', 'Groovy Chick: My Fashion World on NDS allows you to express your style. Create trendy outfits, decorate your room, and hang out with friends in a vibrant world full of creativity and fashion-forward fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grosse-tagesschau-quiz-das-germany', 'NDS', 'Grosse Tagesschau Quiz, Das (Germany)', '2008', 'Quiz', 'SevenOne Interactive', '1', 'TV', 'Trivia and quiz.', 'Answer current events and history questions to win.', 'A trivia game based on Germany''s famous news program.', 'Das Grosse Tagesschau Quiz on NDS tests your knowledge of world events. With thousands of questions based on decades of news coverage, it''s a challenging experience for news junkies and trivia fans alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grundschule-1-4-klasse---fit-fuers-gymnasium-germany', 'NDS', 'Grundschule 1.-4. Klasse - Fit fuers Gymnasium (Germany)', '2008', 'Educational', 'Tivola', '1', 'Kids', 'Educational and exam prep.', 'Prepare for the transition from primary school to gymnasium.', 'A comprehensive study aid for German elementary students.', 'Fit fuers Gymnasium on NDS covers all essential subjects needed for the entrance to the Gymnasium school level. It features structured lessons and practice tests to ensure students are ready for the next step.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grundschule-1-4-klasse---fit-fuers-gymnasium-2010-germany', 'NDS', 'Grundschule 1.-4. Klasse - Fit fuers Gymnasium 2010 (Germany)', '2010', 'Educational', 'Tivola', '1', 'Kids', 'Educational and exam prep.', 'Prepare for the transition from primary school to gymnasium.', 'An updated 2010 edition of the school transition trainer.', 'Fit fuers Gymnasium 2010 provides updated curriculum-based exercises on NDS. Students can practice Math, German, and English through interactive drills designed to build confidence for their upcoming school changes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guida-in-cucina-la---che-si-mangia-oggi-italy', 'NDS', 'Guida in Cucina, La - Che Si Mangia Oggi (Italy)', '2009', 'Simulation', 'Leader', '1', 'Cooking', 'Cooking simulation.', 'Follow recipes and prepare authentic Italian dishes.', 'An interactive cookbook and cooking game in Italian.', 'La Guida in Cucina on NDS is both a game and a tool. Learn hundreds of recipes, follow step-by-step cooking instructions, and play mini-games to master the art of Italian cuisine in your own kitchen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guilty-gear---dust-strikers-europe-enfrdeesit', 'NDS', 'Guilty Gear - Dust Strikers (Europe) (En,Fr,De,Es,It)', '2006', 'Fighting', 'Arc System Works', '4', 'Anime', '2D Fighting.', 'Fight on four platforms and defeat your rivals.', 'A unique multi-level fighter featuring Guilty Gear characters.', 'Guilty Gear: Dust Strikers brings the legendary fighting series to NDS. Battle across both screens on four different levels, use special items, and master the signature moves of Sol Badguy and the rest of the cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guilty-gear---dust-strikers-japan', 'NDS', 'Guilty Gear - Dust Strikers (Japan)', '2006', 'Fighting', 'Arc System Works', '4', 'Anime', '2D Fighting.', 'Fight on four platforms and defeat your rivals.', 'A unique multi-level fighter featuring Guilty Gear characters.', 'Guilty Gear: Dust Strikers brings the legendary fighting series to NDS. Battle across both screens on four different levels, use special items, and master the signature moves of Sol Badguy and the rest of the cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guilty-gear---dust-strikers-usa', 'NDS', 'Guilty Gear - Dust Strikers (USA)', '2006', 'Fighting', 'Arc System Works', '4', 'Anime', '2D Fighting.', 'Fight on four platforms and defeat your rivals.', 'A unique multi-level fighter featuring Guilty Gear characters.', 'Guilty Gear: Dust Strikers brings the legendary fighting series to NDS. Battle across both screens on four different levels, use special items, and master the signature moves of Sol Badguy and the rest of the cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guinness-world-records---the-videogame-europe-enfrdeesit', 'NDS', 'Guinness World Records - The Videogame (Europe) (En,Fr,De,Es,It)', '2008', 'Compilation', 'Glimmer Holding', '1', 'Records', 'Mini-game collection.', 'Break world records through various wacky challenges.', 'A competitive collection of games based on the world records.', 'Guinness World Records: The Videogame for NDS lets you attempt the impossible. From the fastest time eating a plane to long-distance jumps, compete in crazy mini-games to get your name in the digital book of records.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guinness-world-records---the-videogame-usa-enfres', 'NDS', 'Guinness World Records - The Videogame (USA) (En,Fr,Es)', '2008', 'Compilation', 'Glimmer Holding', '1', 'Records', 'Mini-game collection.', 'Break world records through various wacky challenges.', 'A competitive collection of games based on the world records.', 'Guinness World Records: The Videogame for NDS lets you attempt the impossible. From the fastest time eating a plane to long-distance jumps, compete in crazy mini-games to get your name in the digital book of records.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guitar-hero---on-tour---decades-europe', 'NDS', 'Guitar Hero - On Tour - Decades (Europe)', '2009', 'Music', 'Vicarious Visions', '1', 'Rhythm', 'Rhythm and music.', 'Master rock classics from different decades and become a legend.', 'A journey through rock history with portable guitar gameplay.', 'Guitar Hero On Tour: Decades for NDS lets you rock out to hits from the 70s, 80s, 90s, and 2000s. Use the Guitar Grip to shred through a legendary tracklist, unlock new characters, and prove your skills in Career mode.');
