INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guitar-hero---on-tour---modern-hits-europe', 'NDS', 'Guitar Hero - On Tour - Modern Hits (Europe)', '2009', 'Music', 'Vicarious Visions', '1', 'Rhythm', 'Rhythm and music.', 'Play the biggest contemporary rock hits on the go.', 'Modern rock anthems meet the innovative Guitar Grip.', 'Guitar Hero On Tour: Modern Hits focuses on the hottest tracks of the 21st century. Conquer the setlist with the stylus and buttons, experience a deep career mode, and challenge friends to wireless face-offs.');
