INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guitar-hero---on-tour-europe', 'NDS', 'Guitar Hero - On Tour (Europe)', '2008', 'Music', 'Vicarious Visions', '1', 'Rhythm', 'Rhythm and music.', 'Shred through iconic rock songs and climb the charts.', 'The game that brought the Guitar Hero fever to the NDS.', 'Guitar Hero On Tour revolutionized portable rhythm gaming. Using the innovative Guitar Grip, hit the notes in time with the music to earn high scores and unlock new gear in this high-voltage rock experience.');
