INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guitar-rock-tour-europe-enfrdeesitnl', 'NDS', 'Guitar Rock Tour (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Music', 'Game Republic', '1', 'Rhythm', 'Rhythm and music.', 'Play guitar or drums to the beat of popular rock songs.', 'A fast-paced arcade-style guitar and drum simulation.', 'Guitar Rock Tour for NDS offers a high-energy music experience. Whether you''re playing the guitar or hitting the drums, follow the rhythm to master famous hits and become a worldwide rock sensation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guitar-rock-tour-usa-enfres', 'NDS', 'Guitar Rock Tour (USA) (En,Fr,Es)', '2008', 'Music', 'Game Republic', '1', 'Rhythm', 'Rhythm and music.', 'Play guitar or drums to the beat of popular rock songs.', 'A fast-paced arcade-style guitar and drum simulation.', 'Guitar Rock Tour for NDS offers a high-energy music experience. Whether you''re playing the guitar or hitting the drums, follow the rhythm to master famous hits and become a worldwide rock sensation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunpey-ds---music-x-puzzle-europe-enfrdeesit', 'NDS', 'Gunpey DS - Music x Puzzle (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'Q-Games', '1', 'MusicPuzzle', 'Puzzle and music.', 'Connect lines across the screen to clear the board.', 'A stylish and rhythmic evolution of the Gunpey puzzle.', 'Gunpey DS combines fast-paced line-matching with dynamic music. Use the stylus to flip lines, create connections from left to right, and enjoy a vibrant audiovisual experience designed by the creator of the Game Boy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunpey-ds---music-x-puzzle-usa', 'NDS', 'Gunpey DS - Music x Puzzle (USA)', '2007', 'Puzzle', 'Q-Games', '1', 'MusicPuzzle', 'Puzzle and music.', 'Connect lines across the screen to clear the board.', 'A stylish and rhythmic evolution of the Gunpey puzzle.', 'Gunpey DS combines fast-paced line-matching with dynamic music. Use the stylus to flip lines, create connections from left to right, and enjoy a vibrant audiovisual experience designed by the creator of the Game Boy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guru-guru-europe-enfrdeesit', 'NDS', 'Guru Guru (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Magic Pockets', '1', 'Casual', 'Action and puzzle.', 'Control a rotating wand to navigate through mazes.', 'A whimsical and colorful maze-navigation adventure.', 'Guru Guru on NDS challenges your precision and timing. Rotate your character to move through obstacle-filled levels, collect items, and solve physics-based puzzles in this unique and charming Japanese-style title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guruguru-nagetto-japan', 'NDS', 'Guruguru Nagetto (Japan)', '2009', 'Puzzle', 'Jaleco', '1', 'Casual', 'Action and puzzle.', 'Guide the Guruguru creatures to safety through obstacles.', 'A fast-paced puzzle action game featuring cute characters.', 'Guruguru Nagetto for NDS requires quick thinking and stylus accuracy. Maneuver your characters through tricky environments, dodge enemies, and reach the goal in this colorful and addictive Japanese experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakkyou-burai-kaiji---death-or-survival-japan', 'NDS', 'Gyakkyou Burai Kaiji - Death or Survival (Japan)', '2007', 'Adventure', 'Compile Heart', '1', 'Anime', 'Psychological gambling and simulation.', 'Survive high-stakes death games through strategy and luck.', 'A dark psychological thriller based on the Kaiji anime.', 'Gyakkyou Burai Kaiji on NDS plunges you into a world of debt and dangerous gambling. Master games like Restricted Rock-Paper-Scissors and E-Card to survive the brutal traps set by the Teiai Corporation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakuten-kenji-japan', 'NDS', 'Gyakuten Kenji (Japan)', '2009', 'Adventure', 'Capcom', '1', 'VisualNovel', 'Visual novel and investigation.', 'Investigate crime scenes as prosecutor Miles Edgeworth.', 'A spin-off of the Ace Attorney series focused on logic.', 'Gyakuten Kenji (Miles Edgeworth: Investigations) shifts the focus from the courtroom to the crime scene. Deduce the truth by connecting evidence and using Miles''s signature "Logic" system to find contradictions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakuten-kenji-2-japan', 'NDS', 'Gyakuten Kenji 2 (Japan)', '2011', 'Adventure', 'Capcom', '1', 'VisualNovel', 'Visual novel and investigation.', 'Solve complex cases and uncover a deep conspiracy.', 'The highly-acclaimed sequel to Miles Edgeworth''s solo debut.', 'Gyakuten Kenji 2 follows Miles Edgeworth as he faces his greatest challenges yet. Introducing the "Logic Chess" mechanic, this title offers deep storytelling and more complex investigations in the Ace Attorney universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakuten-saiban---yomigaeru-gyakuten-japan-enja', 'NDS', 'Gyakuten Saiban - Yomigaeru Gyakuten (Japan) (En,Ja)', '2005', 'Adventure', 'Capcom', '1', 'VisualNovel', 'Visual novel and courtroom drama.', 'Defend your clients and find the real criminal in court.', 'The definitive NDS remake of the first Phoenix Wright.', 'Gyakuten Saiban (Phoenix Wright: Ace Attorney) introduces the rookie lawyer. Cross-examine witnesses, yell "Objection!", and use the NDS touch screen and mic to present evidence and solve five thrilling cases.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakuten-saiban-2-japan-enja', 'NDS', 'Gyakuten Saiban 2 (Japan) (En,Ja)', '2006', 'Adventure', 'Capcom', '1', 'VisualNovel', 'Visual novel and courtroom drama.', 'Use the Psyche-Lock system to uncover hidden secrets.', 'The second chapter in the Phoenix Wright trilogy.', 'Gyakuten Saiban 2 (Justice for All) raises the stakes. Introducing the "Magatama" and Psyche-Locks, Phoenix must see through the lies of witnesses to protect the innocent in four high-tension courtroom battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakuten-saiban-3-japan-enja', 'NDS', 'Gyakuten Saiban 3 (Japan) (En,Ja)', '2007', 'Adventure', 'Capcom', '1', 'VisualNovel', 'Visual novel and courtroom drama.', 'Uncover the past to save the future of the legal system.', 'The epic conclusion to the original Phoenix Wright trilogy.', 'Gyakuten Saiban 3 (Trials and Tribulations) features multiple protagonists and a gripping story. Link the past and present as you face off against the mysterious Godot in the ultimate legal showdown.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakuten-saiban-4-japan', 'NDS', 'Gyakuten Saiban 4 (Japan)', '2007', 'Adventure', 'Capcom', '1', 'VisualNovel', 'Visual novel and courtroom drama.', 'Master the "Perceive" system as new lawyer Apollo Justice.', 'A new era for the series featuring a new protagonist.', 'Gyakuten Saiban 4 (Apollo Justice: Ace Attorney) moves the timeline forward. Use Apollo''s special ability to detect nervous tics in witnesses and discover the truth in a world where the law has changed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakuten-saiban-jiten-japan', 'NDS', 'Gyakuten Saiban Jiten (Japan)', '2009', 'Educational', 'Capcom', '1', 'Reference', 'Digital Encyclopedia.', 'Explore the lore, characters, and cases of the series.', 'A comprehensive digital archive for Ace Attorney fans.', 'Gyakuten Saiban Jiten is the ultimate reference guide for NDS. Browse detailed character bios, listen to the iconic soundtrack, and review case details from the first three games in this interactive encyclopedia.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyouretsu-no-dekiru---houritsu-soudanjo-japan', 'NDS', 'Gyouretsu no Dekiru - Houritsu Soudanjo (Japan)', '2008', 'Educational', 'Success', '1', 'Simulation', 'Legal consultation and simulation.', 'Solve legal disputes based on the popular Japanese TV show.', 'A lighthearted law-themed simulation and quiz game.', 'Gyouretsu no Dekiru Houritsu Soudanjo puts you in the hot seat of a legal consultation office. Listen to various cases, consult with famous TV lawyers, and learn about Japanese law through engaging interactive scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('habu-yoshiharu-shougi-de-kitaeru---ketsudanryoku-ds-japan', 'NDS', 'Habu Yoshiharu Shougi de Kitaeru - Ketsudanryoku DS (Japan)', '2007', 'BoardGame', 'Success', '1', 'Strategy', 'Board game and strategy.', 'Master the art of Shougi under the guidance of a pro.', 'A deep Shougi (Japanese chess) trainer for all levels.', 'Habu Yoshiharu Shougi de Kitaeru offers professional-grade tutorials and AI opponents. Learn the "Decision Making" skills of grandmaster Yoshiharu Habu to improve your strategy and master this classic board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hachi-one-diver-ds-japan', 'NDS', 'Hachi-One Diver DS (Japan)', '2008', 'Sports', 'KCEJ', '1', 'Anime', 'Board game and story.', 'Win high-stakes Shougi matches to protect your secret life.', 'A story-driven Shougi game based on the popular manga.', 'Hachi-One Diver DS follows the journey of a professional "Shougi diver." Engage in intense, high-speed matches and follow a dramatic narrative as you climb the ranks of the underground gambling world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hagane-no-renkinjutsushi---dual-sympathy-japan', 'NDS', 'Hagane no Renkinjutsushi - Dual Sympathy (Japan)', '2005', 'Action', 'Artoon', '1', 'Anime', 'Side-scrolling beat ''em up.', 'Use alchemy to battle enemies and find the Philosopher''s Stone.', 'The Japanese edition of the action-packed FMA adventure.', 'Fullmetal Alchemist: Dual Sympathy brings Ed and Al Elric''s quest to the NDS. Use the touch screen to draw transmutation circles and unleash powerful alchemic attacks against the Homunculi in this faithful anime adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hajime-no-ippo---the-fighting!-ds-japan', 'NDS', 'Hajime no Ippo - The Fighting! DS (Japan)', '2008', 'Sports', 'Grand Prix', '1', 'Boxing', 'Boxing simulation and action.', 'Climb the ranks and win the championship as Ippo Makunouchi.', 'A high-energy boxing game based on the legendary manga.', 'Hajime no Ippo: The Fighting! DS brings the thrill of the ring to your handheld. Use the stylus for precise punches and dodges, experience the epic story of Ippo, and master signature moves to KO your opponents in this intense sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hakoniwa-seikatsu---hitsuji-mura-ds-japan', 'NDS', 'Hakoniwa Seikatsu - Hitsuji Mura DS (Japan)', '2008', 'Simulation', 'Success', '1', 'LifeSim', 'Farming and life simulation.', 'Manage a farm and raise sheep in a peaceful village.', 'A relaxing rural life simulator with a focus on livestock.', 'Hakoniwa Seikatsu: Hitsuji Mura DS lets you experience country living. Plant crops, breed animals, and trade goods with villagers. It’s a charming, slower-paced sim perfect for fans of the Harvest Moon series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hakuouki-ds-japan', 'NDS', 'Hakuouki DS (Japan)', '2009', 'Adventure', 'Idea Factory', '1', 'VisualNovel', 'Otome visual novel.', 'Navigate a historical romance during the Bakumatsu era.', 'A high-stakes romance with the warriors of the Shinsengumi.', 'Hakuouki DS brings the acclaimed samurai visual novel to NDS. Make critical choices to build relationships with legendary warriors while uncovering a supernatural mystery in 19th-century Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamekomi-lucky-puzzle-ds-japan-enja', 'NDS', 'Hamekomi Lucky Puzzle DS (Japan) (En,Ja)', '2009', 'Puzzle', 'Compile Heart', '1', 'Casual', 'Puzzle and logic.', 'Fit various geometric shapes into a specific silhouette.', 'A classic and addictive shape-fitting puzzle game.', 'Hamekomi Lucky Puzzle DS challenges your spatial reasoning. With hundreds of levels ranging from simple to complex, use the stylus to rotate and place pieces to complete each design perfectly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hammer-bro', 'NDS', 'Hammer Bro', '2008', 'Action', 'Nintendo', '1', 'Platformer', 'Character Swap (Mod).', 'Play through the game with Hammer Bro''s unique style.', 'A fun modification featuring the classic Mario enemy.', 'Hammer Bro for NDS is a fan-favorite character swap that brings the hammer-tossing Koopa into new adventures. Experience classic levels with a fresh perspective and the iconic look of the Hammer Bro.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamster-to-kurasou-japan', 'NDS', 'Hamster to Kurasou (Japan)', '2006', 'Simulation', 'Success', '1', 'PetSim', 'Virtual pet simulation.', 'Breed, feed, and play with your pet hamsters.', 'A cute and detailed hamster raising simulation.', 'Hamster to Kurasou on NDS lets you create a home for adorable hamsters. Clean their cages, give them treats, and watch them interact with toys in this heartwarming and portable pet simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamster-to-kurasou-japan-rev-1', 'NDS', 'Hamster to Kurasou (Japan) (Rev 1)', '2006', 'Simulation', 'Success', '1', 'PetSim', 'Virtual pet simulation.', 'Breed, feed, and play with your pet hamsters.', 'A cute and detailed hamster raising simulation.', 'Hamster to Kurasou on NDS lets you create a home for adorable hamsters. Clean their cages, give them treats, and watch them interact with toys in this heartwarming and portable pet simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamsterz-2-europe-enfrdeesitnl-rev-1', 'NDS', 'Hamsterz 2 (Europe) (En,Fr,De,Es,It,Nl) (Rev 1)', '2007', 'Simulation', 'Raylight Studios', '1', 'PetSim', 'Virtual pet simulation.', 'Raise a family of hamsters and win pet competitions.', 'An expanded pet sim with more breeds and activities.', 'Hamsterz 2 offers a deep pet-care experience on NDS. Train your hamsters to perform tricks, customize their habitats with various items, and enter them into shows to prove they are the cutest in the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamsterz-life-europe', 'NDS', 'Hamsterz Life (Europe)', '2006', 'Simulation', 'Raylight Studios', '1', 'PetSim', 'Virtual pet simulation.', 'Take care of your hamster and keep it happy and healthy.', 'A simple and fun pet simulator for all ages.', 'Hamsterz Life on NDS is a great introduction to the virtual pet genre. Choose your favorite breed, talk to your pet using the microphone, and build a lasting bond through daily care and play sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamsterz-life-usa', 'NDS', 'Hamsterz Life (USA)', '2006', 'Simulation', 'Raylight Studios', '1', 'PetSim', 'Virtual pet simulation.', 'Take care of your hamster and keep it happy and healthy.', 'A simple and fun pet simulator for all ages.', 'Hamsterz Life on NDS is a great introduction to the virtual pet genre. Choose your favorite breed, talk to your pet using the microphone, and build a lasting bond through daily care and play sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hana-deka-club---animal-paradise-japan', 'NDS', 'Hana Deka Club - Animal Paradise (Japan)', '2008', 'Simulation', 'Success', '1', 'AnimalCare', 'Photography and pet care.', 'Take photos of adorable animals with "big heads".', 'A unique photography game featuring the "The Dog" art style.', 'Hana Deka Club: Animal Paradise lets you play with and photograph cute animals. Earn their trust to take the perfect "fish-eye" lens photo, a hallmark of the popular Japanese franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hana-saku-ds-gardening-life-japan', 'NDS', 'Hana Saku DS Gardening Life (Japan)', '2007', 'Simulation', 'Nintendo', '1', 'Gardening', 'Gardening simulation.', 'Cultivate a beautiful flower garden through various seasons.', 'A peaceful and colorful flower growing simulator.', 'Hana Saku DS Gardening Life turns your NDS into a digital garden. Learn about different flower species, manage water and sunlight, and create stunning floral arrangements in this relaxing Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hana-to-taiyou-to-ame-to---owaranai-rakuen-japan', 'NDS', 'Hana to Taiyou to Ame to - Owaranai Rakuen (Japan)', '2008', 'Adventure', 'Grasshopper Manufacture', '1', 'Narrative', 'Surreal mystery adventure.', 'Solve puzzles to break a time loop on a tropical island.', 'The original Japanese version of the cult-classic Suda51 game.', 'Flower, Sun and Rain (Hana to Taiyou to Ame to) is a unique detective adventure. Use the "L some" suitcase to solve numerical codes and uncover the secrets of Loro Island in this bizarre and stylish journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hana-yori-dango---koi-seyo-otome!-japan', 'NDS', 'Hana Yori Dango - Koi Seyo Otome! (Japan)', '2008', 'Adventure', 'Idea Factory', '1', 'Romance', 'Visual novel and romance.', 'Win the heart of one of the "F4" elite students.', 'A high-school romance based on the famous manga.', 'Hana Yori Dango for NDS follows the story of Tsukushi at Eitoku Academy. Interact with the rich and handsome F4 members, make choices that influence the plot, and experience a classic shojo romance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hands-on!-tangrams-usa', 'NDS', 'Hands On! Tangrams (USA)', '2008', 'Puzzle', 'Crave Entertainment', '1', 'Educational', 'Logic puzzle.', 'Solve traditional Tangram puzzles using the touch screen.', 'A portable version of the ancient Chinese dissection puzzle.', 'Hands On! Tangrams features over 100 puzzles to challenge your brain. Use the stylus to drag, flip, and rotate the seven "tans" to match the target shapes in this clean and relaxing puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('haneru-no-tobira-ds---tanshuku-tetsudou-no-yoru-japan', 'NDS', 'Haneru no Tobira DS - Tanshuku Tetsudou no Yoru (Japan)', '2008', 'Variety', 'Namco', '1', 'Comedy', 'Mini-game collection.', 'Play games based on the popular Japanese variety show.', 'A fun collection of games featuring the "Railway" segment.', 'Haneru no Tobira DS brings the humor of the TV show to NDS. Engage in rhythm-based word games and reflex challenges inspired by the "Tanshuku Tetsudou" skits with the Fuji TV cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hanguk-eomungyoyuk-yeonguhoe---hangeom-ds-korea', 'NDS', 'Hanguk-eomungyoyuk-yeonguhoe - Hangeom DS (Korea)', '2007', 'Educational', 'Daesung', '1', 'LanguageLearning', 'Educational and language.', 'Study and pass the Korean Hanja (Chinese character) exam.', 'A comprehensive study tool for Korean language learners.', 'Hanguk-eomungyoyuk-yeonguhoe: Hangeom DS is a professional-grade trainer for the national Hanja proficiency test. Practice writing characters and learn their meanings through structured drills and mock exams.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hank-j-wimbleton-over-luigi', 'NDS', 'Hank J. Wimbleton over Luigi', '2007', 'Action', 'Independent', '1', 'Arcade', 'Character Swap (Mod).', 'Battle through the world as the relentless Hank J. Wimbleton.', 'A high-octane mod featuring the protagonist of Madness Combat.', 'Hank J. Wimbleton over Luigi brings a gritty, action-focused aesthetic to the game. Play as the legendary mercenary with custom sprites that transform the experience into a "Madness" themed adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hannah-montana---music-jam-europe-enfrdeesitnl', 'NDS', 'Hannah Montana - Music Jam (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Music', 'EA Canada', '1', 'Rhythm', 'Rhythm and music.', 'Create your own songs and live the life of a pop star.', 'A musical adventure featuring Miley Cyrus''s alter ego.', 'Hannah Montana: Music Jam on NDS lets you play guitar, drums, and bass using the touch screen. Record your own tracks, film music videos, and compete in the ultimate "Music Jam" to become a superstar.');
