INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hannah-montana---the-movie-europe', 'NDS', 'Hannah Montana - The Movie (Europe)', '2009', 'Adventure', 'EA Canada', '1', 'MovieTieIn', 'Adventure and rhythm.', 'Help Miley choose between her celebrity life and Crowley Corners.', 'The official game based on the Hannah Montana movie.', 'Hannah Montana: The Movie on NDS follows the film''s plot. Perform on stage, customize your outfits, and complete tasks in Miley’s hometown to learn the value of staying true to yourself.');
