INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hannah-montana-europe-enfrdeesitnl', 'NDS', 'Hannah Montana (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Adventure', 'EA Canada', '1', 'MusicAdventure', 'Action adventure.', 'Live the secret life of a pop star and navigate high school.', 'An adventure game based on the hit Disney Channel series.', 'Hannah Montana on NDS lets you explore iconic locations from the show. Use gadgets to avoid fans, solve puzzles, and help Miley Stewart keep her secret identity safe in this fun-filled quest.');
