INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hanshin-tigers-ds-japan', 'NDS', 'Hanshin Tigers DS (Japan)', '2007', 'Sports', 'Nintendo', '1', 'Baseball', 'Sports trivia and simulation.', 'Manage the team and answer questions about the Hanshin Tigers.', 'A specialized fan game for the famous Japanese baseball team.', 'Hanshin Tigers DS is a must-have for supporters. It features a deep database of team history, player stats, and interactive trivia, allowing you to prove you are the ultimate Tigers enthusiast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hapi-hapi-clover-japan', 'NDS', 'Hapi Hapi Clover (Japan)', '2007', 'Adventure', 'Alchemist', '1', 'Anime', 'Life simulation and mini-games.', 'Live a forest life with Chibi Clover and his animal friends.', 'A cute and colorful simulation based on the shojo manga.', 'Hapi Hapi Clover on NDS is a delightful experience for young players. Explore the forest, play mini-games, and build friendships with adorable rabbits and other woodland creatures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('happy-bakery-europe-enfrdeesit', 'NDS', 'Happy Bakery (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Neko Entertainment', '1', 'TimeManagement', 'Cooking and management.', 'Bake delicious treats and run a successful bakery.', 'A sweet and engaging bakery management simulator.', 'Happy Bakery on NDS tasks you with mixing ingredients, decorating cakes, and serving hungry customers. Unlock new recipes and expand your shop to become the most famous baker in town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('happy-cooking---touch-pen-de-tanoshiku-oryouri-japan', 'NDS', 'Happy Cooking - Touch Pen de Tanoshiku Oryouri (Japan)', '2007', 'Simulation', 'Unknown', '1', 'Cooking', 'Cooking simulation.', 'Prepare delicious meals through fun touch-screen games.', 'An interactive cooking game for aspiring young chefs.', 'Happy Cooking on NDS features dozens of recipes to master. Use the stylus to chop, stir, and fry your way to culinary perfection, earning high scores and new kitchen tools as you go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('happy-cooking-usa', 'NDS', 'Happy Cooking (USA)', '2008', 'Simulation', 'Digital Eclipse', '1', 'Cooking', 'Cooking simulation.', 'Prepare delicious meals through fun touch-screen games.', 'An interactive cooking game for aspiring young chefs.', 'Happy Cooking on NDS features dozens of recipes to master. Use the stylus to chop, stir, and fry your way to culinary perfection, earning high scores and new kitchen tools as you go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('happy-feet-europe-enfrdeesit', 'NDS', 'Happy Feet (Europe) (En,Fr,De,Es,It)', '2006', 'Adventure', 'A2M', '1', 'MovieTieIn', 'Rhythm and adventure.', 'Help Mumble find his soulmate through dance and song.', 'A fun musical adventure based on the animated film.', 'Happy Feet on NDS lets you tap to the beat. Guide Mumble through the icy Antarctic, winning dance-offs and completing rhythm challenges to prove that being different is a gift in this charming movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('happy-feet-usa', 'NDS', 'Happy Feet (USA)', '2006', 'Adventure', 'A2M', '1', 'MovieTieIn', 'Rhythm and adventure.', 'Help Mumble find his soulmate through dance and song.', 'A fun musical adventure based on the animated film.', 'Happy Feet on NDS lets you tap to the beat. Guide Mumble through the icy Antarctic, winning dance-offs and completing rhythm challenges to prove that being different is a gift in this charming movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('happy-hippos-world-tour-europe-enfrdeesit', 'NDS', 'Happy Hippo''s World Tour (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Tate Interactive', '1', 'Family', 'Mini-game collection.', 'Travel the world and win various international challenges.', 'A wacky global tour featuring the Happy Hippo characters.', 'Happy Hippo''s World Tour on NDS takes you on a trip across continents. Compete in diverse mini-games themed after different cultures and landmarks, all while enjoying the humorous antics of the famous Ferrero mascots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('happy-my-sweets-japan', 'NDS', 'Happy My Sweets (Japan)', '2008', 'Simulation', 'Nintendo', '1', 'Cooking', 'Simulation and cooking.', 'Create delicious sweets and manage your own candy shop.', 'A colorful Japanese confectionery management sim.', 'Happy My Sweets on NDS lets you become a master pastry chef. Use the touch screen to mix, bake, and decorate adorable treats. Attract customers with your sweet creations and grow your shop into a local favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('happy-party-with-hello-kitty-&-friends!-europe-enfrdeesitnl', 'NDS', 'Happy Party with Hello Kitty & Friends! (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Party', 'Bit Managers', '4', 'PartyGame', 'Party games and social.', 'Host the best party ever with Hello Kitty and her pals.', 'A sweet mini-game collection for Hello Kitty fans.', 'Happy Party with Hello Kitty & Friends! brings Sanrio magic to NDS. Participate in various party-themed mini-games, help your friends with their tasks, and earn rewards to decorate and host the ultimate celebration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('happy-star-band-japan', 'NDS', 'Happy Star Band (Japan)', '2007', 'Music', 'Nintendo', '1', 'Rhythm', 'Rhythm and music.', 'Lead your band to stardom through musical performances.', 'A high-energy Japanese music and rhythm game.', 'Happy Star Band on NDS challenges your sense of rhythm. Choose your instruments, practice your tracks, and perform on stage to win over fans and become the most popular band in the galaxy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hardy-boys-the---treasure-on-the-tracks-europe-enfrderu', 'NDS', 'Hardy Boys, The - Treasure on the Tracks (Europe) (En,Fr,De,Ru)', '2009', 'Adventure', 'The Adventure Company', '1', 'Detective', 'Hidden object and mystery.', 'Solve a mystery on a train journey across Europe.', 'A classic detective adventure starring the Hardy Boys.', 'The Hardy Boys: Treasure on the Tracks on NDS puts you in the middle of a high-stakes investigation. Search for hidden clues, solve complex puzzles, and interview suspects to uncover a legendary hidden treasure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hardy-boys-the---treasure-on-the-tracks-usa', 'NDS', 'Hardy Boys, The - Treasure on the Tracks (USA)', '2009', 'Adventure', 'The Adventure Company', '1', 'Detective', 'Hidden object and mystery.', 'Solve a mystery on a train journey across Europe.', 'A classic detective adventure starring the Hardy Boys.', 'The Hardy Boys: Treasure on the Tracks on NDS puts you in the middle of a high-stakes investigation. Search for hidden clues, solve complex puzzles, and interview suspects to uncover a legendary hidden treasure.');
