INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harobots-action!!-japan', 'NDS', 'Harobots Action!! (Japan)', '2007', 'Action', 'Namco', '1', 'Arcade', 'Action and mecha battling.', 'Control robots based on the Hello Kitty universe.', 'A unique action-battle game featuring the Harobots.', 'Harobots Action!! on NDS combines mecha combat with iconic Japanese characters. Customize your robot, engage in fast-paced battles, and use special abilities to defeat rivals in this eccentric and colorful action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-and-the-deathly-hallows---part-1-europe-enfrdeesit', 'NDS', 'Harry Potter and the Deathly Hallows - Part 1 (Europe) (En,Fr,De,Es,It)', '2010', 'Adventure', 'EA Bright Light', '1', 'MovieTieIn', 'Action and magic combat.', 'Find and destroy Voldemort''s Horcruxes.', 'A gritty action-adventure based on the first half of the final film.', 'Harry Potter and the Deathly Hallows Part 1 on NDS features intense spell-casting combat. Use the stylus to aim and fire spells, use the Invisibility Cloak for stealth, and survive the hunt outside of Hogwarts.');
