INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-and-the-deathly-hallows---part-2-europe-enfrdeesit', 'NDS', 'Harry Potter and the Deathly Hallows - Part 2 (Europe) (En,Fr,De,Es,It)', '2011', 'Adventure', 'EA Bright Light', '1', 'MovieTieIn', 'Action and magic combat.', 'Defeat Voldemort in the final battle for Hogwarts.', 'The epic conclusion to the Harry Potter saga in game form.', 'Harry Potter and the Deathly Hallows Part 2 on NDS brings the final showdown to life. Play as Harry and his friends as you fight through the ruins of Hogwarts, using powerful magic to end the Dark Lord''s reign once and for all.');
