INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-to-honoo-no-goblet-japan', 'NDS', 'Harry Potter to Honoo no Goblet (Japan)', '2005', 'Adventure', 'EA UK', '1', 'Magic', 'Action adventure and sports.', 'Compete in the Triwizard Tournament and solve mysteries.', 'The Japanese edition of the Goblet of Fire.', 'Harry Potter to Honoo no Goblet features the three protagonists in their most dangerous year yet. Use teamwork and magic to survive the Triwizard tasks and the graveyard encounter on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-to-nazo-no-prince-japan-enja', 'NDS', 'Harry Potter to Nazo no Prince (Japan) (En,Ja)', '2009', 'Adventure', 'EA Bright Light', '1', 'Magic', 'Adventure and alchemy.', 'Discover the identity of the Half-Blood Prince.', 'The Japanese edition of the Half-Blood Prince.', 'Harry Potter to Nazo no Prince on NDS offers a mix of narrative and mini-games. Perfect your potion-brewing skills and help Harry uncover the memories of the past to prepare for the future.');
