INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potterwa-honhyeorwangja-korea', 'NDS', 'Harry Potterwa Honhyeorwangja (Korea)', '2009', 'Adventure', 'EA Bright Light', '1', 'Magic', 'Adventure and alchemy.', 'Discover the identity of the Half-Blood Prince.', 'The Korean edition of the Half-Blood Prince.', 'Harry Potterwa Honhyeorwangja on NDS translates the magical journey for Korean players. Explore the castle, participate in wizarding duels, and uncover the truth behind the Half-Blood Prince''s book.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-fishing-europe-enfrdeesit', 'NDS', 'Harvest Fishing (Europe) (En,Fr,De,Es,It)', '2007', 'Simulation', 'Nintendo', '1', 'Fishing', 'Fishing and RPG.', 'Catch the legendary "King Fish" and improve your skills.', 'A relaxing and deep fishing game in the Harvest Moon style.', 'Harvest Fishing (River King) on NDS offers a peaceful outdoor experience. Explore various environments, upgrade your fishing gear, and catch hundreds of species while helping the local town in this charming spin-off.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon---frantic-farming-europe', 'NDS', 'Harvest Moon - Frantic Farming (Europe)', '2009', 'Simulation', 'Natsume', '1', 'Farming', 'Puzzle and farming.', 'Solve match-3 puzzles to harvest crops and save the island.', 'A fast-paced puzzle game set in the Harvest Moon world.', 'Harvest Moon: Frantic Farming on NDS combines strategy and farming. Clear the screen of crops as quickly as possible to win, choosing from multiple characters with unique abilities in this addictive puzzle spin-off.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon---frantic-farming-usa', 'NDS', 'Harvest Moon - Frantic Farming (USA)', '2009', 'Simulation', 'Natsume', '1', 'Farming', 'Puzzle and farming.', 'Solve match-3 puzzles to harvest crops and save the island.', 'A fast-paced puzzle game set in the Harvest Moon world.', 'Harvest Moon: Frantic Farming on NDS combines strategy and farming. Clear the screen of crops as quickly as possible to win, choosing from multiple characters with unique abilities in this addictive puzzle spin-off.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-ds---grand-bazaar-usa', 'NDS', 'Harvest Moon DS - Grand Bazaar (USA)', '2008', 'Simulation', 'Marvelous', '1', 'Farming', 'Farming and economy sim.', 'Run a successful farm and sell goods at the weekly bazaar.', 'A trade-focused entry in the Harvest Moon series.', 'Harvest Moon DS: Grand Bazaar focuses on the market. Grow crops and raise animals to sell your high-quality goods at the bustling weekly town bazaar. Improve your farm and compete with other vendors to have the most successful shop in the valley.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-ds---island-of-happiness-europe-enfrdeesit', 'NDS', 'Harvest Moon DS - Island of Happiness (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Marvelous', '1', 'Farming', 'Farming and colony building.', 'Develop a deserted island into a thriving community.', 'A touch-controlled farming adventure on a remote island.', 'Harvest Moon DS: Island of Happiness uses full touch-screen controls. Start with nothing on a deserted island, grow crops, and build houses to attract new settlers. Marry a sweetheart and watch your small farm grow into a vibrant, happy town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-ds---island-of-happiness-usa', 'NDS', 'Harvest Moon DS - Island of Happiness (USA)', '2008', 'Simulation', 'Marvelous', '1', 'Farming', 'Farming and colony building.', 'Develop a deserted island into a thriving community.', 'A touch-controlled farming adventure on a remote island.', 'Harvest Moon DS: Island of Happiness uses full touch-screen controls. Start with nothing on a deserted island, grow crops, and build houses to attract new settlers. Marry a sweetheart and watch your small farm grow into a vibrant, happy town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-ds---sunshine-islands-europe-enfrdeesit', 'NDS', 'Harvest Moon DS - Sunshine Islands (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Marvelous', '1', 'Farming', 'Farming and exploration.', 'Find Sun Stones to raise sunken islands from the sea.', 'A sequel to Island of Happiness with classic controls.', 'Harvest Moon DS: Sunshine Islands takes you to a vast archipelago. Raise sunken islands to discover new areas, meet magical characters, and expand your farm in this deep and rewarding simulation that returns to traditional button controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-ds---sunshine-islands-usa', 'NDS', 'Harvest Moon DS - Sunshine Islands (USA)', '2009', 'Simulation', 'Marvelous', '1', 'Farming', 'Farming and exploration.', 'Find Sun Stones to raise sunken islands from the sea.', 'A sequel to Island of Happiness with classic controls.', 'Harvest Moon DS: Sunshine Islands takes you to a vast archipelago. Raise sunken islands to discover new areas, meet magical characters, and expand your farm in this deep and rewarding simulation that returns to traditional button controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-ds-europe-enfrdeesit', 'NDS', 'Harvest Moon DS (Europe) (En,Fr,De,Es,It)', '2005', 'Simulation', 'Marvelous', '1', 'Farming', 'Farming and life simulation.', 'Restore the Harvest Sprite Company and find the Harvest Goddess.', 'The classic Harvest Moon experience on the dual screen.', 'Harvest Moon DS brings the beloved farming formula to NDS. Plant crops, raise livestock, and explore the town to find all 101 Harvest Sprites. Court a local bachelorette and build a lasting legacy in the beautiful Forget-Me-Not Valley.');
