INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-ds-usa-rev-1', 'NDS', 'Harvest Moon DS (USA) (Rev 1)', '2005', 'Simulation', 'Marvelous', '1', 'Farming', 'Farming and life simulation.', 'Restore the Harvest Sprite Company and find the Harvest Goddess.', 'The classic Harvest Moon experience on the dual screen.', 'Harvest Moon DS brings the beloved farming formula to NDS. Plant crops, raise livestock, and explore the town to find all 101 Harvest Sprites. Court a local bachelorette and build a lasting legacy in the beautiful Forget-Me-Not Valley.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-ds-cute-usa', 'NDS', 'Harvest Moon DS Cute (USA)', '2008', 'Simulation', 'Marvelous', '1', 'Farming', 'Farming and life simulation.', 'Play as a girl, manage a farm, and find the perfect husband.', 'The female-protagonist version of the classic Harvest Moon DS.', 'Harvest Moon DS Cute lets you choose between two female characters. Manage your farm, interact with the valley''s residents, and woo your favorite bachelor while working to restore the Harvest Goddess and her sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hasbro-family-game-night-europe-enfrdenl', 'NDS', 'Hasbro Family Game Night (Europe) (En,Fr,De,Nl)', '2009', 'Party', 'EA Bright Light', '4', 'BoardGame', 'Board game collection.', 'Win classic board games in a virtual family setting.', 'A collection of Hasbro''s most famous tabletop games.', 'Hasbro Family Game Night features classics like Operation, Connect 4, Battleship, and Bop It. Play with friends or family in local wireless mode and enjoy modern twists on the board games everyone knows and loves.');
