INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('haus-anubis-das---das-geheimnis-des-osiris-germany', 'NDS', 'Haus Anubis, Das - Das Geheimnis des Osiris (Germany)', '2009', 'Adventure', 'Studio100', '1', 'Mystery', 'Adventure and mystery.', 'Solve the mystery of Osiris in the boarding school.', 'A mystery-adventure based on the German teen TV show.', 'Das Haus Anubis on NDS takes you inside the mysterious boarding school. Explore secret rooms, solve environmental puzzles, and uncover the ancient secrets of Osiris in this suspenseful game for fans of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hayarigami-2-ds---toshi-densetsu-kaii-jiken-japan', 'NDS', 'Hayarigami 2 DS - Toshi Densetsu Kaii Jiken (Japan)', '2007', 'Adventure', 'Nippon Ichi', '1', 'Horror', 'Visual novel and horror.', 'Investigate terrifying urban legends and solve mysteries.', 'A psychological horror adventure based on urban myths.', 'Hayarigami 2 DS plunges you into the world of the supernatural. As a detective, choose between the scientific or occult path to solve gruesome cases inspired by Japanese urban legends in this atmospheric narrative game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hayarigami-ds---toshi-densetsu-kaii-jiken-japan', 'NDS', 'Hayarigami DS - Toshi Densetsu Kaii Jiken (Japan)', '2006', 'Adventure', 'Nippon Ichi', '1', 'Horror', 'Visual novel and horror.', 'Investigate terrifying urban legends and solve mysteries.', 'A psychological horror adventure based on urban myths.', 'Hayarigami DS is a police-procedural horror title. Navigate through dark investigations where your choices determine the truth. Use the "Self-Questioning" system to narrow down suspects in this chilling mystery experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hayate-no-gotoku!---boku-ga-romeo-de-romeo-ga-boku-de-japan', 'NDS', 'Hayate no Gotoku! - Boku ga Romeo de Romeo ga Boku de (Japan)', '2011', 'VisualNovel', 'Guyzware', '1', 'Romance', 'Visual novel and comedy.', 'Navigate a hilarious story as Hayate the butler.', 'A humorous adventure based on the popular anime series.', 'Hayate no Gotoku! for NDS lets you experience the chaotic life of Hayate. Make choices to balance your duties as a butler while interacting with Nagi and the rest of the cast in this lighthearted and funny visual novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hayate-no-gotoku!---ojousama-produce-daisakusen---boku-iro-ni-somare!---gakkou-hen-japan', 'NDS', 'Hayate no Gotoku! - Ojousama Produce Daisakusen - Boku Iro ni Somare! - Gakkou Hen (Japan)', '2010', 'Simulation', 'Guyzware', '1', 'LifeSim', 'Simulation and management.', 'Train your lady to be the best student at school.', 'A lady-producing simulation game for NDS.', 'Ojousama Produce Daisakusen (School Edition) tasks you with managing the social and academic life of the series'' heroines. Improve their stats through mini-games and events to help them shine in the school environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hayate-no-gotoku!---ojousama-produce-daisakusen---boku-iro-ni-somare!---oyashiki-hen-japan', 'NDS', 'Hayate no Gotoku! - Ojousama Produce Daisakusen - Boku Iro ni Somare! - Oyashiki Hen (Japan)', '2010', 'Simulation', 'Guyzware', '1', 'LifeSim', 'Simulation and management.', 'Train your lady to be a proper heiress at the mansion.', 'A lady-producing simulation game focused on estate life.', 'Ojousama Produce Daisakusen (Mansion Edition) focuses on the home life of the Hayate cast. Train the girls in etiquette and personal skills through interactive mini-games to turn them into perfect ladies of the house.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heartcatch-precure!---oshare-collection-japan', 'NDS', 'HeartCatch PreCure! - Oshare Collection (Japan)', '2010', 'Simulation', 'Bandai Namco', '1', 'Fashion', 'Fashion and mini-games.', 'Collect outfits and play games with the HeartCatch girls.', 'A colorful fashion and rhythm game for PreCure fans.', 'HeartCatch PreCure! Oshare Collection is filled with magical girl fun. Design cute outfits, participate in rhythm-based dance challenges, and explore the world of the anime through engaging touch-screen activities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heathcliff!---frantic-foto-usa-enfres', 'NDS', 'Heathcliff! - Frantic Foto (USA) (En,Fr,Es)', '2009', 'Action', 'Imagitec', '1', 'Arcade', 'Puzzle and observation.', 'Find the differences in images of the famous cat.', 'A "spot the difference" game featuring Heathcliff.', 'Heathcliff! Frantic Foto on NDS features the classic orange comic cat. Race against the clock to find subtle differences in vibrant illustrations, perfect for fans of the character and puzzle lovers alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heavy-armor-brigade-usa', 'NDS', 'Heavy Armor Brigade (USA)', '2008', 'Action', 'Vanguard', '1', 'Shooter', 'Tank combat simulation.', 'Lead your tank brigade to victory in military missions.', 'A tactical armored warfare game for the NDS.', 'Heavy Armor Brigade offers intense tank battles. Command a variety of armored vehicles, use the dual screens to manage tactics and aim, and complete challenging missions in this military-focused action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heisa-byoutou---dementium-japan', 'NDS', 'Heisa Byoutou - Dementium (Japan)', '2007', 'Adventure', 'Success', '1', 'Horror', 'First-person horror.', 'Survive the nightmare of a haunted psychiatric hospital.', 'A terrifying survival horror game with FPS elements.', 'Heisa Byoutou (Dementium: The Ward) on NDS is a true horror experience. Explore dark corridors with a flashlight, solve twisted puzzles, and fight grotesque monsters in a haunted asylum using a precision touch-aiming system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heisei-kyouiku-iinkai-ds---zenkoku-touitsu-moshi-special-japan', 'NDS', 'Heisei Kyouiku Iinkai DS - Zenkoku Touitsu Moshi Special (Japan)', '2009', 'Education', 'Nintendo', '1', 'Education', 'Trivia and educational.', 'Answer a variety of school subjects to pass the exam.', 'A comprehensive quiz game based on the TV show.', 'Heisei Kyouiku Iinkai DS tests your knowledge of math, science, and history. Compete in national-style mock exams and track your "educational level" through thousands of challenging questions on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heisei-kyouiku-iinkai-ds-japan', 'NDS', 'Heisei Kyouiku Iinkai DS (Japan)', '2006', 'Education', 'Nintendo', '1', 'Education', 'Trivia and educational.', 'Answer a variety of school subjects to pass the exam.', 'A comprehensive quiz game based on the TV show.', 'Heisei Kyouiku Iinkai DS tests your knowledge of math, science, and history. Compete in national-style mock exams and track your "educational level" through thousands of challenging questions on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hells-kitchen---the-game-europe-enfrdeesit', 'NDS', 'Hell''s Kitchen - The Game (Europe) (En,Fr,De,Es,It)', '2010', 'Simulation', 'Ludometrics', '1', 'Cooking', 'Cooking and management.', 'Survive the kitchen and impress Chef Gordon Ramsay.', 'A fast-paced cooking game based on the reality TV show.', 'Hell''s Kitchen: The Game on NDS puts you under the pressure of a professional kitchen. Prepare ingredients, cook dishes to perfection, and manage the dining room speed to avoid the wrath of Chef Ramsay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hells-kitchen---the-game-usa-enfrdeesit', 'NDS', 'Hell''s Kitchen - The Game (USA) (En,Fr,De,Es,It)', '2010', 'Simulation', 'Ludometrics', '1', 'Cooking', 'Cooking and management.', 'Survive the kitchen and impress Chef Gordon Ramsay.', 'A fast-paced cooking game based on the reality TV show.', 'Hell''s Kitchen: The Game on NDS puts you under the pressure of a professional kitchen. Prepare ingredients, cook dishes to perfection, and manage the dining room speed to avoid the wrath of Chef Ramsay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-baby!-europe-enfrdeesit', 'NDS', 'Hello Baby! (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Namco Bandai', '1', 'Parenting', 'Baby care simulation.', 'Take care of a virtual baby and watch them grow.', 'A realistic and heartwarming baby-care simulator.', 'Hello Baby! on NDS lets you experience parenthood. Feed, bathe, and play with your virtual baby using the touch screen and microphone. Learn their needs and unlock new items as you build a bond with your digital child.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty---big-city-dreams-europe-enfrdeesitnlpt', 'NDS', 'Hello Kitty - Big City Dreams (Europe) (En,Fr,De,Es,It,Nl,Pt)', '2008', 'Adventure', 'Sanrio', '1', 'LifeSim', 'Adventure and social sim.', 'Help Hello Kitty move to the city and make her dreams come true.', 'A charming social adventure featuring Hello Kitty.', 'Hello Kitty: Big City Dreams on NDS takes the famous kitten to the big city. Explore different neighborhoods, play fun mini-games to earn friendship points, and customize your apartment in this delightful and colorful journey.');
