INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty---birthday-adventures-europe-enfrdeesit', 'NDS', 'Hello Kitty - Birthday Adventures (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Sanrio', '1', 'LifeSim', 'Adventure and mini-games.', 'Plan and attend birthday parties for your Sanrio friends.', 'A birthday-themed adventure with Hello Kitty.', 'Hello Kitty: Birthday Adventures on NDS lets you explore the town and help your friends prepare for their special days. Collect items, complete quests, and enjoy a variety of festive mini-games in this heartwarming title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty---birthday-adventures-usa-enfrdeesit', 'NDS', 'Hello Kitty - Birthday Adventures (USA) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Sanrio', '1', 'LifeSim', 'Adventure and mini-games.', 'Plan and attend birthday parties for your Sanrio friends.', 'A birthday-themed adventure with Hello Kitty.', 'Hello Kitty: Birthday Adventures on NDS lets you explore the town and help your friends prepare for their special days. Collect items, complete quests, and enjoy a variety of festive mini-games in this heartwarming title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty---daily-europe', 'NDS', 'Hello Kitty - Daily (Europe)', '2008', 'Simulation', 'Sanrio', '1', 'LifeSim', 'Organizer and lifestyle.', 'Use Hello Kitty tools to organize your daily life.', 'A personal digital assistant and diary with Sanrio style.', 'Hello Kitty Daily on NDS turns your console into a complete organizer. Manage your calendar, track your expenses, and write in your private diary, all while enjoying the cute and colorful company of Hello Kitty.');
