INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty---party-usa-enfrdeesitnl', 'NDS', 'Hello Kitty - Party (USA) (En,Fr,De,Es,It,Nl)', '2009', 'Party', 'Sanrio', '4', 'PartyGame', 'Party games and social.', 'Host the best party ever with Hello Kitty and her pals.', 'A sweet mini-game collection for Hello Kitty fans.', 'Hello Kitty Party brings Sanrio magic to NDS. Participate in various party-themed mini-games, help your friends with their tasks, and earn rewards to decorate and host the ultimate celebration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty-no-gotouchi-collection---koi-no-dokidoki-travel-japan', 'NDS', 'Hello Kitty no Gotouchi Collection - Koi no DokiDoki Travel (Japan)', '2009', 'Adventure', 'Sanrio', '1', 'Travel', 'Travel simulation and collection.', 'Travel across Japan and collect regional Hello Kitty items.', 'A charming journey to discover local Japanese specialties.', 'Hello Kitty no Gotouchi Collection features a travel-themed adventure. Visit different prefectures, learn about regional culture, and collect unique "Gotouchi Kitty" charms in this relaxing Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty-no-oshare-party---sanrio-character-zukan-ds-japan', 'NDS', 'Hello Kitty no Oshare Party - Sanrio Character Zukan DS (Japan)', '2008', 'Simulation', 'Sanrio', '1', 'Fashion', 'Mini-game collection.', 'Play games and unlock a Sanrio character encyclopedia.', 'A fun game and guide featuring all your favorite Sanrio pals.', 'Hello Kitty no Oshare Party on NDS is a must-have for fans. Complete fashion and logic mini-games to unlock entries in the digital character book, featuring over 100 characters from the Sanrio universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty-no-paku-paku-&-logic-japan', 'NDS', 'Hello Kitty no Paku Paku & Logic (Japan)', '2008', 'Puzzle', 'Sanrio', '1', 'Logic', 'Puzzle and logic.', 'Solve Picross-style logic puzzles to reveal images.', 'A fun and cute logic-puzzle game featuring Hello Kitty.', 'Hello Kitty no Paku Paku & Logic offers a wide variety of "Nonogram" puzzles. Use the touch screen to fill in the grid and reveal adorable pixel-art images of Hello Kitty and her friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty-no-panda-sports-stadium-japan', 'NDS', 'Hello Kitty no Panda Sports Stadium (Japan)', '2008', 'Sports', 'Sanrio', '1', 'Arcade', 'Sports simulation.', 'Compete in various athletic events with Hello Kitty.', 'A cute and accessible sports game for young players.', 'Hello Kitty no Panda Sports Stadium features a range of Olympic-style mini-games. From running to jumping, use the stylus to help Hello Kitty win gold medals in this colorful sports stadium.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-pocoyo!-europe-enfrdeesit', 'NDS', 'Hello, Pocoyo! (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Zinkia', '1', 'Educational', 'Educational and adventure.', 'Explore and play with Pocoyo and his friends.', 'A playful educational game based on the hit preschool show.', 'Hello, Pocoyo! on NDS is designed for the youngest players. Solve simple puzzles, play music, and interact with Pocoyo, Pato, and Elly in a colorful world that encourages curiosity and learning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('henry-hatsworth-in-the-puzzling-adventure-europe-enfrdeesit', 'NDS', 'Henry Hatsworth in the Puzzling Adventure (Europe) (En,Fr,De,Es,It)', '2009', 'ActionPuzzle', 'EA Tiburon', '1', 'PuzzlePlatformer', 'Action-platformer and puzzle.', 'Battle enemies on the top screen while solving puzzles on the bottom.', 'A brilliant hybrid of 2D action and match-3 puzzles.', 'Henry Hatsworth in the Puzzling Adventure is a unique NDS gem. Defeat monsters in a platforming world and clear blocks on the "Puzzle Realm" to gain power-ups and mana in this challenging adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('henry-hatsworth-in-the-puzzling-adventure-usa-enfrdeesit', 'NDS', 'Henry Hatsworth in the Puzzling Adventure (USA) (En,Fr,De,Es,It)', '2009', 'ActionPuzzle', 'EA Tiburon', '1', 'PuzzlePlatformer', 'Action-platformer and puzzle.', 'Battle enemies on the top screen while solving puzzles on the bottom.', 'A brilliant hybrid of 2D action and match-3 puzzles.', 'Henry Hatsworth in the Puzzling Adventure is a unique NDS gem. Defeat monsters in a platforming world and clear blocks on the "Puzzle Realm" to gain power-ups and mana in this challenging adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heracles---battle-with-the-gods-europe-enfrdeesit', 'NDS', 'Heracles - Battle with the Gods (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Titus', '1', 'BeatEmUp', 'Action-adventure and platformer.', 'Battle gods and mythical beasts to prove your worth.', 'A fast-paced platformer based on Greek mythology.', 'Heracles: Battle with the Gods on NDS takes you to ancient Greece. Use Heracles'' incredible strength and special abilities to navigate levels, defeat legendary bosses, and earn your place among the Olympians.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heracles-no-eikou---tamashii-no-shoumei-japan', 'NDS', 'Heracles no Eikou - Tamashii no Shoumei (Japan)', '2007', 'Action', 'Paon', '1', 'ActionAdventure', 'Turn-based RPG.', 'Guide an immortal hero through a world of Greek myths.', 'The Japanese edition of the epic Glory of Heracles RPG.', 'Heracles no Eikou on NDS features a deep story and a unique battle system. Customize your skills with ether and embark on a grand quest alongside legendary figures in this beautifully crafted fantasy adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('herbie---rescue-rally-europe-enfrdees', 'NDS', 'Herbie - Rescue Rally (Europe) (En,Fr,De,Es)', '2009', 'Racing', 'ArtificialMind', '1', 'Arcade', 'Racing and mission-based action.', 'Win races and complete rescue missions with the Love Bug.', 'A fun racing game featuring the iconic VW Beetle, Herbie.', 'Herbie: Rescue Rally on NDS offers a mix of high-speed racing and environmental challenges. Use Herbie’s special moves to overcome obstacles and win the championship in this family-friendly racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('herbie---rescue-rally-usa-enfrdees', 'NDS', 'Herbie - Rescue Rally (USA) (En,Fr,De,Es)', '2009', 'Racing', 'ArtificialMind', '1', 'Arcade', 'Racing and mission-based action.', 'Win races and complete rescue missions with the Love Bug.', 'A fun racing game featuring the iconic VW Beetle, Herbie.', 'Herbie: Rescue Rally on NDS offers a mix of high-speed racing and environmental challenges. Use Herbie’s special moves to overcome obstacles and win the championship in this family-friendly racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heros-saga---laevatein-tactics-usa', 'NDS', 'Hero''s Saga - Laevatein Tactics (USA)', '2009', 'TacticalRPG', 'GStyle', '1', 'Strategy', 'Tactical RPG.', 'Lead your army to victory using powerful legendary swords.', 'A strategic fantasy RPG with deep customization.', 'Hero''s Saga: Laevatein Tactics on NDS features grid-based combat. Equip your heroes with Vaethir blades, choose your classes wisely, and conquer the battlefield in this epic story of war and magic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heroes-of-mana-europe', 'NDS', 'Heroes of Mana (Europe)', '2007', 'ActionRPG', 'BrownieBrown', '1', 'ActionRPG', 'Real-time strategy (RTS).', 'Defend the kingdom and manage resources in the Mana world.', 'A tactical spin-off of the beloved Mana series.', 'Heroes of Mana on NDS uses the touch screen for strategic troop management. Build bases, gather resources, and lead your units in real-time battles to uncover the secrets of the world tree.');
