INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hexe-lilli-entdeckt-europa-germany', 'NDS', 'Hexe Lilli Entdeckt Europa (Germany)', '2009', 'Adventure', 'Kiddinx', '1', 'Educational', 'Educational and adventure.', 'Explore European countries and learn interesting facts.', 'A fun geography lesson featuring Bibi Blocksberg''s friend.', 'Hexe Lilli Entdeckt Europa on NDS teaches kids about European geography and culture. Join Lilli on her magical journey, solve puzzles, and learn about different nations in this educational adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hi-hi-puffy-amiyumi---the-genie-&-the-amp-europe-enfrdeesit', 'NDS', 'Hi Hi Puffy AmiYumi - The Genie & the Amp (Europe) (En,Fr,De,Es,It)', '2006', 'Action', 'ArtificialMind', '1', 'Platformer', 'Action-adventure.', 'Travel through time and defeat the genie to save rock and roll.', 'A quirky adventure based on the Cartoon Network show.', 'Hi Hi Puffy AmiYumi: The Genie & the Amp takes the rock stars on a time-traveling quest. Fight through different eras using your instruments as weapons in this colorful and humorous action title.');
