INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hidden-mysteries---titanic---secrets-of-the-fateful-voyage-europe-enfrit', 'NDS', 'Hidden Mysteries - Titanic - Secrets of the Fateful Voyage (Europe) (En,Fr,It)', '2010', 'HiddenObject', 'Playlogic', '1', 'Mystery', 'Hidden object and mystery.', 'Escape the sinking ship by finding clues and solving puzzles.', 'A dramatic hidden object adventure set on the Titanic.', 'Hidden Mysteries: Titanic on NDS puts you aboard the ill-fated vessel. Search through detailed rooms, collect essential items, and solve challenging riddles to find your way to safety before the ship sinks in this atmospheric mystery.');
