INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hidden-objects---mystery-stories-usa-enfres', 'NDS', 'Hidden Objects - Mystery Stories (USA) (En,Fr,Es)', '2009', 'HiddenObject', 'G5Entertainment', '1', 'Mystery', 'Hidden object and puzzle.', 'Solve various criminal cases and mysteries by finding clues.', 'A collection of detective-themed hidden object levels.', 'Hidden Objects: Mystery Stories for NDS challenges your observation skills. Search across multiple crime scenes, find the requested objects, and piece together the narrative to solve each case.');
