INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('higurashi-no-naku-koro-ni-kizuna-i-japan', 'NDS', 'Higurashi no Naku Koro ni Kizuna I (Japan)', '2008', 'VisualNovel', 'Alchemist', '1', 'Horror', 'Visual novel and horror.', 'Uncover the mystery of the Hinamizawa village curse.', 'A psychological horror masterpiece on the NDS.', 'Higurashi no Naku Koro ni Kizuna I is the first volume of the "When They Cry" saga. Experience a deep, branching narrative filled with suspense, tragedy, and supernatural mystery in this atmospheric visual novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('higurashi-no-naku-koro-ni-kizuna-ii---dainikan---sou-japan', 'NDS', 'Higurashi no Naku Koro ni Kizuna II - Dainikan - Sou (Japan)', '2008', 'VisualNovel', 'Alchemist', '1', 'Horror', 'Visual novel and horror.', 'Survive the repeating cycles of tragedy in Hinamizawa.', 'The second chapter of the terrifying Higurashi saga.', 'Higurashi Kizuna II continues the dark story with new arcs. Make choices that influence the fate of the characters and attempt to solve the gruesome murders that plague the village.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('higurashi-no-naku-koro-ni-kizuna-iii---daisankan---rasen-japan', 'NDS', 'Higurashi no Naku Koro ni Kizuna III - Daisankan - Rasen (Japan)', '2009', 'VisualNovel', 'Alchemist', '1', 'Horror', 'Visual novel and horror.', 'Piece together the truth behind the mysterious disappearances.', 'The third intense installment of the Higurashi series.', 'Higurashi Kizuna III adds even more depth to the mystery. Navigate through a psychological thriller where every decision could lead to a horrific end or the key to the truth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('higurashi-no-naku-koro-ni-kizuna-iv---daiyonkan---kizuna-japan', 'NDS', 'Higurashi no Naku Koro ni Kizuna IV - Daiyonkan - Kizuna (Japan)', '2010', 'VisualNovel', 'Alchemist', '1', 'Horror', 'Visual novel and horror.', 'Reach the final conclusion and break the curse of Hinamizawa.', 'The epic finale of the Higurashi Kizuna series.', 'Higurashi Kizuna IV brings the saga to its shocking conclusion. Solve the ultimate riddle of the village and protect your friends in this final, emotionally-charged visual novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hiiro-no-kakera-ds-japan', 'NDS', 'Hiiro no Kakera DS (Japan)', '2010', 'VisualNovel', 'IdeaFactory', '1', 'Romance', 'Otome visual novel.', 'Protect the village and build a romance with your guardians.', 'A classic supernatural romance for NDS.', 'Hiiro no Kakera DS follows the story of the Tamayori Princess. Interact with handsome guardians, use mystical powers, and experience a deep narrative filled with Japanese folklore and romantic choices.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hiite-utaeru-ds-guitar-m-06-japan', 'NDS', 'Hiite Utaeru DS Guitar ''M-06'' (Japan)', '2008', 'Rhythm', 'Success', '1', 'Music', 'Music simulation.', 'Learn to play guitar using the NDS touch screen.', 'A portable guitar trainer and simulation tool.', 'Hiite Utaeru DS Guitar turns your console into a virtual instrument. Use the stylus to strum strings and master chords, perfect for practicing your favorite songs or learning the basics of the guitar.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hijouguchi---exit-ds-japan', 'NDS', 'Hijouguchi - Exit DS (Japan)', '2008', 'Adventure', 'CompileHeart', '1', 'Horror', 'Puzzle and platformer.', 'Guide Mr. ESC out of dangerous buildings before time runs out.', 'A stylish escape-puzzle game with a sleek look.', 'Hijouguchi: Exit DS challenges your brain. Lead civilians to safety through traps and obstacles across 100 levels. Use the touch screen to command followers and find the exit in this unique tactical puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hikari-no-4-senshi---final-fantasy-gaiden-japan', 'NDS', 'Hikari no 4 Senshi - Final Fantasy Gaiden (Japan)', '2009', 'RPG', 'SquareEnix', '1', 'Fantasy', 'Turn-based RPG.', 'Embark on a grand quest to save the world as a Light Warrior.', 'A beautiful and classic Final Fantasy adventure.', 'Hikari no 4 Senshi (Final Fantasy: The 4 Heroes of Light) features a stunning storybook art style. Master the Crown System for job changes and engage in classic turn-based combat in this nostalgic RPG for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hippatte!!-puzzle-bobble-japan', 'NDS', 'Hippatte!! Puzzle Bobble (Japan)', '2008', 'Puzzle', 'Taito', '1', 'Arcade', 'Puzzle and action.', 'Pull and shoot bubbles to match colors and clear the screen.', 'A unique touch-screen take on the Puzzle Bobble series.', 'Hippatte!! Puzzle Bobble (Space Buster) uses a pulling mechanic for the stylus. Shoot bubbles upward across both screens to pop them and defeat space-themed bosses in this addictive arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hiraki-kazuo-sensei-tokyo-daigaku-kanshuu---suku-suku-kosodate-ds---akachan-to-asobou!-japan', 'NDS', 'Hiraki Kazuo Sensei (Tokyo Daigaku) Kanshuu - Suku Suku Kosodate DS - Akachan to Asobou! (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Parenting', 'Educational and parenting.', 'Play with your baby and track their early development.', 'A specialized parenting aid and baby-interaction game.', 'Suku Suku Kosodate DS offers advice and games for new parents. Interact with your virtual baby to encourage growth and learn valuable child-rearing tips supervised by experts from Tokyo University.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hirameki-action---chibikko-wagyan-no-ooki-na-bouken-japan', 'NDS', 'Hirameki Action - Chibikko Wagyan no Ooki na Bouken (Japan)', '2009', 'Action', 'BandaiNamco', '1', 'Platformer', 'Action-adventure.', 'Save the world with Wagyan''s voice-power and mini-games.', 'A colorful revival of the classic Wagyan Land series.', 'Chibikko Wagyan no Ooki na Bouken features the iconic dinosaur using his "shout" to freeze enemies. Complete platforming levels and engage in unique "Shiritori" and puzzle boss battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hirameki-puzzle---maxwell-no-fushigi-na-note-japan', 'NDS', 'Hirameki Puzzle - Maxwell no Fushigi na Note (Japan)', '2009', 'Puzzle', 'Konami', '1', 'Logic', 'Creative puzzle and sandbox.', 'Solve puzzles by writing names of objects to bring them to life.', 'The Japanese version of the innovative Scribblenauts.', 'Maxwell no Fushigi na Note (Scribblenauts) lets your imagination run wild. Write almost any word to summon the object and use it to solve tricky environmental puzzles in this award-winning creative title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hiromichi-oniisan-no-oyako-taisou-navi---oyako-no-skin-ship-&-tairyoku-zukuri-japan', 'NDS', 'Hiromichi Oniisan no Oyako Taisou Navi - Oyako no Skin-Ship & Tairyoku Zukuri (Japan)', '2008', 'Educational', 'Benesse', '1', 'Fitness', 'Health and fitness.', 'Exercise with your child to build strength and bonds.', 'A family-focused fitness and gymnastics guide.', 'Oyako Taisou Navi provides interactive routines for parents and kids. Follow the guidance of Hiromichi-oniisan to improve physical health and strengthen family ties through fun, simple exercises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hissatsu-kung-fu---kanji-dragon-japan', 'NDS', 'Hissatsu Kung Fu - Kanji Dragon (Japan)', '2009', 'Action', 'Success', '1', 'Educational', 'Educational and combat.', 'Defeat dragons by correctly writing Kanji characters.', 'A kanji-learning game wrapped in a kung fu adventure.', 'Kanji Dragon turns studying into a battle. Use the stylus to write Japanese characters quickly and accurately to unleash kung fu attacks and defeat mythical enemies in this educational action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hisshou-pachinko-pachi-slot-kouryaku-series-ds-vol-1---shinseiki-evangelion---magokoro-o-kimi-ni-japan', 'NDS', 'Hisshou Pachinko Pachi-Slot Kouryaku Series DS Vol. 1 - Shinseiki Evangelion - Magokoro o, Kimi ni (Japan)', '2008', 'Gambling', 'D3Publisher', '1', 'Simulation', 'Casino simulation.', 'Master the Evangelion-themed Pachi-Slot machines.', 'An authentic simulation of the Evangelion Pachi-Slot.', 'Hisshou Pachinko Series Vol. 1 brings the thrill of Japanese parlors to your NDS. Practice your timing on the "Magokoro o, Kimi ni" machine, analyze data, and experience the iconic Eva visuals in this detailed gambling sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hisshou-pachinko-pachi-slot-kouryaku-series-ds-vol-2---cr-shinseiki-evangelion---shito-futatabi-japan', 'NDS', 'Hisshou Pachinko Pachi-Slot Kouryaku Series DS Vol. 2 - CR Shinseiki Evangelion - Shito, Futatabi (Japan)', '2008', 'Gambling', 'D3Publisher', '1', 'Simulation', 'Casino simulation.', 'Master the Evangelion-themed Pachinko machines.', 'A realistic simulation of the "Shito, Futatabi" machine.', 'Hisshou Pachinko Series Vol. 2 focuses on the popular "Shito, Futatabi" Pachinko model. Featuring cinematic cutscenes from the anime, this sim allows you to test strategies and enjoy the flashing lights of the parlor anywhere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hisshou-pachinko-pachi-slot-kouryaku-series-ds-vol-3---shinseiki-evangelion---yakusoku-no-toki-japan', 'NDS', 'Hisshou Pachinko Pachi-Slot Kouryaku Series DS Vol. 3 - Shinseiki Evangelion - Yakusoku no Toki (Japan)', '2009', 'Gambling', 'D3Publisher', '1', 'Simulation', 'Casino simulation.', 'Master the Evangelion-themed Pachi-Slot machines.', 'A faithful recreation of the "Yakusoku no Toki" slot.', 'Hisshou Pachinko Series Vol. 3 offers a deep dive into the mechanics of the "Yakusoku no Toki" machine. Use the NDS touch screen to pull the lever and master the bonus rounds featuring Shinji and the Evas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hisshou-pachinko-pachi-slot-kouryaku-series-ds-vol-4---cr-shinseiki-evangelion---saigo-no-shisha-japan', 'NDS', 'Hisshou Pachinko Pachi-Slot Kouryaku Series DS Vol. 4 - CR Shinseiki Evangelion - Saigo no Shisha (Japan)', '2009', 'Gambling', 'D3Publisher', '1', 'Simulation', 'Casino simulation.', 'Master the Evangelion-themed Pachinko machines.', 'A simulation of the "Saigo no Shisha" Pachinko model.', 'Hisshou Pachinko Series Vol. 4 brings the "Saigo no Shisha" experience to the dual screen. Explore the intricate payout systems and enjoy high-quality animations based on the legendary Neon Genesis Evangelion series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hisshou-pachinko-pachi-slot-kouryaku-series-ds-vol-5---shinseiki-evangelion---tamashii-no-kiseki-japan', 'NDS', 'Hisshou Pachinko Pachi-Slot Kouryaku Series DS Vol. 5 - Shinseiki Evangelion - Tamashii no Kiseki (Japan)', '2010', 'Gambling', 'D3Publisher', '1', 'Simulation', 'Casino simulation.', 'Master the Evangelion-themed Pachi-Slot machines.', 'The fifth installment featuring "Tamashii no Kiseki".', 'Hisshou Pachinko Series Vol. 5 completes the Eva collection on NDS. Featuring the "Tamashii no Kiseki" machine, it provides detailed statistics, gallery modes, and perfect Pachi-Slot emulation for fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('histoire-de-france-pour-les-nuls-l-france', 'NDS', 'Histoire de France pour les Nuls, L'' (France)', '2009', 'Educational', 'Mindscape', '1', 'History', 'Educational and trivia.', 'Learn the history of France through interactive lessons.', 'A fun and accessible history guide for the "Dummies" series.', 'L''Histoire de France pour les Nuls on NDS makes learning history engaging. From the Gauls to modern times, test your knowledge with quizzes, timelines, and fun facts in this comprehensive French educational title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('history---great-empires---rome-europe-enfrdeesit', 'NDS', 'History - Great Empires - Rome (Europe) (En,Fr,De,Es,It)', '2009', 'Strategy', 'Slitherine', '1', 'Historical', 'Turn-based strategy.', 'Build and lead the Roman Empire to global dominance.', 'A deep historical strategy game set in ancient Rome.', 'History: Great Empires - Rome on NDS lets you command legions and manage resources. Expand your borders, engage in tactical turn-based battles, and relive the rise of one of history''s greatest civilizations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('history---great-empires---rome-usa-enfrdeesit', 'NDS', 'History - Great Empires - Rome (USA) (En,Fr,De,Es,It)', '2009', 'Strategy', 'Slitherine', '1', 'Historical', 'Turn-based strategy.', 'Build and lead the Roman Empire to global dominance.', 'A deep historical strategy game set in ancient Rome.', 'History: Great Empires - Rome on NDS lets you command legions and manage resources. Expand your borders, engage in tactical turn-based battles, and relive the rise of one of history''s greatest civilizations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hmh-vokabeltrainer---englisch-germany', 'NDS', 'HMH Vokabeltrainer - Englisch (Germany)', '2008', 'Educational', 'HMH', '1', 'Language', 'Educational and language.', 'Master English vocabulary through daily exercises.', 'A structured language trainer for German speakers.', 'HMH Vokabeltrainer: Englisch on NDS is a practical tool for learning on the go. Focus on essential vocabulary, practice pronunciation, and track your progress through various interactive language games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hmh-vokabeltrainer---franzoesisch-germany', 'NDS', 'HMH Vokabeltrainer - Franzoesisch (Germany)', '2008', 'Educational', 'HMH', '1', 'Language', 'Educational and language.', 'Master French vocabulary through daily exercises.', 'A structured language trainer for German speakers.', 'HMH Vokabeltrainer: Franzoesisch provides a comprehensive curriculum for learning French. Use the stylus to complete exercises and improve your vocabulary in a fun, mobile-friendly environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hmh-vokabeltrainer---spanisch-germany', 'NDS', 'HMH Vokabeltrainer - Spanisch (Germany)', '2008', 'Educational', 'HMH', '1', 'Language', 'Educational and language.', 'Master Spanish vocabulary through daily exercises.', 'A structured language trainer for German speakers.', 'HMH Vokabeltrainer: Spanisch helps you learn Spanish efficiently on your NDS. Featuring a wide range of topics and difficulty levels, it''s the perfect companion for students and travelers alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hokkaido-hatsu!-dosanko-wide-ga-ds-ni-narimashita---hoshizawa-sachiko-no-temanashi-raku-raku-gohan-japan', 'NDS', 'Hokkaido Hatsu! ''Dosanko Wide'' ga DS ni Narimashita. - Hoshizawa Sachiko no Temanashi Raku Raku Gohan (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Cooking', 'Cooking and lifestyle.', 'Learn easy recipes from the "Dosanko Wide" TV show.', 'A Japanese cooking guide featuring chef Sachiko Hoshizawa.', 'Hokkaido Hatsu! Dosanko Wide on NDS offers hundreds of "stress-free" recipes. Follow step-by-step instructions to create delicious Hokkaido-style meals using the touch screen and voice commands.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hokuto-no-ken---hokuto-shinken-denshousha-no-michi-japan', 'NDS', 'Hokuto no Ken - Hokuto Shinken Denshousha no Michi (Japan)', '2008', 'Action', 'Sega', '1', 'Fighting', '2D Beat ''em up.', 'Defeat rival martial artists as the heir of Hokuto Shinken.', 'A high-octane fighting game based on Fist of the North Star.', 'Hokuto no Ken on NDS brings Kenshiro''s justice to life. Use the stylus to strike the vital "pressure points" of your enemies on the bottom screen while watching the action unfold on top.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hollands-supermodel---win-de-strijd-op-de-catwalk!-netherlands', 'NDS', 'Hollands Supermodel - Win de Strijd op de Catwalk! (Netherlands)', '2009', 'Simulation', 'RealityGames', '1', 'Fashion', 'Fashion and lifestyle.', 'Compete in modeling challenges to win the title.', 'The official Dutch game of Holland''s Next Top Model.', 'Hollands Supermodel on NDS lets you live the life of a catwalk star. Manage your outfits, master the runway walk, and impress the judges in this glamorous modeling simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('holly-hobbie-&-friends-europe-enfrdeesit', 'NDS', 'Holly Hobbie & Friends (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Aquaplus', '1', 'Casual', 'Adventure and mini-games.', 'Help Holly and her friends with their daily adventures.', 'A wholesome game based on the Holly Hobbie brand.', 'Holly Hobbie & Friends on NDS features a series of charming tasks and mini-games. From baking to decorating, join Holly in Clover to learn about friendship and creativity in this sweet title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('holly-hobbie-&-friends-usa', 'NDS', 'Holly Hobbie & Friends (USA)', '2008', 'Adventure', 'Aquaplus', '1', 'Casual', 'Adventure and mini-games.', 'Help Holly and her friends with their daily adventures.', 'A wholesome game based on the Holly Hobbie brand.', 'Holly Hobbie & Friends on NDS features a series of charming tasks and mini-games. From baking to decorating, join Holly in Clover to learn about friendship and creativity in this sweet title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('homie-rollerz-usa-enes', 'NDS', 'Homie Rollerz (USA) (En,Es)', '2008', 'Racing', 'VisualConcepts', '2', 'Arcade', 'Racing and combat.', 'Race through the neighborhood and outrun the competition.', 'A street-racing game featuring the Homies characters.', 'Homie Rollerz on NDS brings the urban culture of the Homies to the track. Customize your lowriders, use power-ups, and race against quirky characters in this fast-paced and colorful arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honeycomb-beat-europe-enfrdeesit', 'NDS', 'Honeycomb Beat (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', 'SonicPowered', '1', 'Music', 'Puzzle and music.', 'Clear hexagonal tiles in sync with the rhythmic beat.', 'A stylish and addictive rhythm-based puzzle game.', 'Honeycomb Beat on NDS challenges your brain and your ears. Flip tiles to match patterns while enjoying a high-energy soundtrack in this unique blend of logic and rhythm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honeycomb-beat-usa', 'NDS', 'Honeycomb Beat (USA)', '2007', 'Puzzle', 'SonicPowered', '1', 'Music', 'Puzzle and music.', 'Clear hexagonal tiles in sync with the rhythmic beat.', 'A stylish and addictive rhythm-based puzzle game.', 'Honeycomb Beat on NDS challenges your brain and your ears. Flip tiles to match patterns while enjoying a high-energy soundtrack in this unique blend of logic and rhythm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horrible-histories---ruthless-romans-europe-enfrdeesit', 'NDS', 'Horrible Histories - Ruthless Romans (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'TGC', '1', 'History', 'Mini-game collection.', 'Survive the life of a Roman through various challenges.', 'A humorous and educational game based on the TV series.', 'Horrible Histories: Ruthless Romans on NDS makes history fun and gross. Engage in gladiator fights, chariot races, and wacky mini-games that highlight the most "horrible" parts of ancient Rome.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horrid-henry---missions-of-mischief-europe-enfrdeesit', 'NDS', 'Horrid Henry - Missions of Mischief (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'AsoboStudio', '1', 'Platformer', 'Platforming and adventure.', 'Help Henry cause chaos and complete his missions.', 'A mischievous platformer based on the Horrid Henry books.', 'Horrid Henry: Missions of Mischief on NDS puts you in the shoes of the ultimate prankster. Use various gadgets to avoid teachers and parents while completing your goals in this fun-filled adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horrid-henrys-horrid-adventure-europe', 'NDS', 'Horrid Henry''s Horrid Adventure (Europe)', '2009', 'Action', 'AsoboStudio', '1', 'Platformer', 'Platforming and adventure.', 'Navigate levels and outsmart everyone in Henry''s world.', 'A high-energy platforming game featuring Horrid Henry.', 'Horrid Henry''s Horrid Adventure on NDS brings the book''s humor to life. Run, jump, and prank your way through several levels of school-based chaos and fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horse-&-foal---my-riding-stables-europe-enesit', 'NDS', 'Horse & Foal - My Riding Stables (Europe) (En,Es,It)', '2008', 'Simulation', 'Tivola', '1', 'Animal', 'Horse simulation.', 'Manage your own stables and care for your horses.', 'A realistic horse management and riding simulator.', 'Horse & Foal: My Riding Stables on NDS lets you build your dream equestrian center. Feed, groom, and train your horses while managing the business and competing in riding events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horse-&-foal---my-riding-stables-europe-enfrde', 'NDS', 'Horse & Foal - My Riding Stables (Europe) (En,Fr,De)', '2008', 'Simulation', 'Tivola', '1', 'Animal', 'Horse simulation.', 'Manage your own stables and care for your horses.', 'A realistic horse management and riding simulator.', 'Horse & Foal: My Riding Stables on NDS lets you build your dream equestrian center. Feed, groom, and train your horses while managing the business and competing in riding events.');
