INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horse-life---adventures-usa-enfres', 'NDS', 'Horse Life - Adventures (USA) (En,Fr,Es)', '2009', 'Simulation', 'KochMedia', '1', 'Animal', 'Horse simulation and adventure.', 'Embark on a journey with your horse and win championships.', 'An adventure-focused entry in the Horse Life series.', 'Horse Life: Adventures on NDS takes you around the world. Choose your breed, train for cross-country events, and uncover a story about the bond between a rider and their horse.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horse-life-usa', 'NDS', 'Horse Life (USA)', '2008', 'Simulation', 'KochMedia', '1', 'Animal', 'Horse simulation.', 'Raise, train, and compete with your favorite horse.', 'A deep and immersive horse life simulator.', 'Horse Life on NDS features realistic care mechanics. Use the touch screen to groom and pet your horse, enter prestigious competitions, and customize your rider''s appearance in this high-quality sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horse-life-3-europe-enfrdeesitnl', 'NDS', 'Horse Life 3 (Europe) (En,Fr,De,Es,It,Nl)', '2012', 'Simulation', 'KochMedia', '1', 'Animal', 'Horse simulation.', 'Travel across continents and master the world of riding.', 'The third installment in the popular horse simulation series.', 'Horse Life 3 on NDS expands the experience with more breeds and beautiful environments. Manage your horse''s stamina, compete in international tournaments, and live the ultimate equestrian dream.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horseland-europe-endenlsv', 'NDS', 'Horseland (Europe) (En,De,Nl,Sv)', '2008', 'Simulation', 'TateInteractive', '1', 'Animal', 'Horse simulation and social.', 'Join the Horseland ranch and bond with your horse.', 'A game based on the animated series Horseland.', 'Horseland on NDS lets you join the famous ranch from the show. Play as your favorite characters, care for their signature horses, and participate in shows to prove you have the best bond.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horseland-europe-frit', 'NDS', 'Horseland (Europe) (Fr,It)', '2008', 'Simulation', 'TateInteractive', '1', 'Animal', 'Horse simulation and social.', 'Join the Horseland ranch and bond with your horse.', 'A game based on the animated series Horseland.', 'Horseland on NDS lets you join the famous ranch from the show. Play as your favorite characters, care for their signature horses, and participate in shows to prove you have the best bond.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horsez-usa-enfres', 'NDS', 'Horsez (USA) (En,Fr,Es)', '2006', 'Simulation', 'Ubisoft', '1', 'Animal', 'Horse simulation.', 'Train your horse and win the world championship.', 'A realistic equestrian simulation for horse lovers.', 'Horsez on NDS lets you experience the life of a professional rider. Groom, feed, and bond with your horse while training in dressage and show jumping to reach the top of the international equestrian world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-no-kirby---sanjou!-dorotche-dan-japan', 'NDS', 'Hoshi no Kirby - Sanjou! Dorotche Dan (Japan)', '2007', 'Platformer', 'HALLaboratory', '1', 'Action', '2D Platforming.', 'Recover Kirby''s stolen strawberry shortcake from the Squeaks.', 'A classic Kirby adventure with copy abilities and treasure hunting.', 'Hoshi no Kirby: Sanjou! Dorotche Dan (Kirby Squeak Squad) features fast-paced platforming. Use the touch screen to mix copy abilities and store items as you track down the infamous Squeak Squad to get your cake back.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-no-kirby-ultra-super-deluxe-japan', 'NDS', 'Hoshi no Kirby Ultra Super Deluxe (Japan)', '2008', 'Platformer', 'HALLaboratory', '1', 'Action', '2D Platforming and mini-games.', 'Complete various adventures and mini-games in the Kirby universe.', 'An expanded remake of the SNES classic Kirby Super Star.', 'Hoshi no Kirby Ultra Super Deluxe (Kirby Super Star Ultra) brings a wealth of content to the NDS. Enjoy revamped classics like "Spring Breeze" and new modes, featuring updated graphics and cooperative gameplay options.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshigami---ruining-blue-earth---remix-usa', 'NDS', 'Hoshigami - Ruining Blue Earth - Remix (USA)', '2007', 'Strategy', 'Sting', '1', 'Tactical', 'Tactical RPG.', 'Lead your army in grid-based battles to save the world.', 'A challenging turn-based tactical RPG with deep systems.', 'Hoshigami: Ruining Blue Earth Remix for NDS features a complex "RAP" gauge system and coin-shield mechanics. Strategize your movements and master elemental magic to survive this punishingly difficult and rewarding strategy classic.');
