INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshizora-navi-japan', 'NDS', 'Hoshizora Navi (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Utility', 'Astronomy Guide.', 'Identify stars and constellations using the DS hardware.', 'An interactive star map and astronomy tool.', 'Hoshizora Navi turns your NDS into a portable planetarium. Using an internal compass in the cartridge (in some versions) or manual inputs, explore the night sky, learn about celestial bodies, and track astronomical events in real-time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshizora-no-comic-garden-japan', 'NDS', 'Hoshizora no Comic Garden (Japan)', '2010', 'Adventure', 'D3Publisher', '1', 'VisualNovel', 'Otome Visual Novel.', 'Build relationships with artists and create your own manga.', 'A romance-themed visual novel with a focus on art.', 'Hoshizora no Comic Garden lets you play as a girl aspiring to be a manga artist. Interact with handsome characters, manage your schedule, and make choices that lead to different romantic outcomes in this charming Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hospital-giant-europe-enfrdeesit', 'NDS', 'Hospital Giant (Europe) (En,Fr,De,Es,It)', '2007', 'Simulation', 'Codemasters', '1', 'Management', 'Management simulation.', 'Build and manage a successful hospital empire.', 'A medical facility tycoon game for the NDS.', 'Hospital Giant on NDS tasks you with designing layouts, hiring staff, and treating patients. Manage budgets and upgrade medical equipment to create the most efficient and prestigious hospital in the city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hot-wheels---battle-force-5-europe-enfrdeesitnl', 'NDS', 'Hot Wheels - Battle Force 5 (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Racing', 'Activision', '2', 'Arcade', 'Vehicular combat and racing.', 'Defeat the Sark and Vandals using high-tech combat vehicles.', 'A fast-paced combat racer based on the TV show.', 'Hot Wheels: Battle Force 5 on NDS puts you in the driver''s seat of advanced battle cars. Engage in high-speed races and use unique weapons to protect Earth from interdimensional threats.');
