INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('i-did-it-mum!---boy-europe-enfrdeesit', 'NDS', 'I Did It Mum! - Boy (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'OXO', '1', 'Kids', 'Educational and mini-games.', 'Complete daily tasks and learn basic life skills.', 'A colorful educational game for young children.', 'I Did It Mum! - Boy on NDS features interactive mini-games designed for toddlers. From dressing up to simple counting, it encourages learning through positive reinforcement and fun activities.');
