INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('i-did-it-mum!---spelling-europe-enfrdeesit', 'NDS', 'I Did It Mum! - Spelling (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'OXO', '1', 'Kids', 'Educational and language.', 'Practice spelling and improve your vocabulary.', 'A fun and simple spelling trainer for kids.', 'I Did It Mum! - Spelling helps young learners master basic words. Through engaging mini-games and writing practice on the touch screen, it makes learning to spell an enjoyable daily habit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('i-did-it-mum!-2---boy-europe-enfrdeesit', 'NDS', 'I Did It Mum! 2 - Boy (Europe) (En,Fr,De,Es,It)', '2010', 'Educational', 'OXO', '1', 'Kids', 'Educational and mini-games.', 'Advance your learning with more complex daily tasks.', 'A sequel to the popular early-learning series for boys.', 'I Did It Mum! 2 - Boy offers expanded challenges on NDS. Featuring new mini-games and higher difficulty levels, it helps growing children continue their developmental journey in a fun way.');
