INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('im-a-celebrity---get-me-out-of-here!-europe', 'NDS', 'I''m a Celebrity - Get Me Out of Here! (Europe)', '2009', 'Simulation', 'FrontierDevelopments', '1', 'Reality', 'Survival mini-games.', 'Survive the jungle and win the celebrity crown.', 'A mini-game collection based on the hit reality TV show.', 'I''m a Celebrity - Get Me Out of Here! for NDS lets you compete in the famous "Bushtucker Trials." Manage your camp, maintain high morale, and survive the jungle''s toughest challenges to avoid elimination.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('icarly---groovy-foodie!-europe', 'NDS', 'iCarly - Groovy Foodie! (Europe)', '2009', 'Simulation', 'BlackLanternStudios', '1', 'Cooking', 'Time management and action.', 'Serve wacky food to customers and help Carly grow her web show.', 'A fast-paced cooking and serving game with the iCarly cast.', 'iCarly: Groovy Foodie! on NDS challenges your speed. Serve Spencer''s bizarre food creations to hungry fans across various locations, using the touch screen to keep up with the frantic pace and unlock new show clips.');
