INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ichido-wa-yon-de-okitai---nihon-bungaku-100-sen-japan', 'NDS', 'Ichido wa Yon de Okitai - Nihon Bungaku 100-sen (Japan)', '2007', 'Educational', 'Gakken', '1', 'Literature', 'Digital Literature.', 'Read 100 classic Japanese literary works on your DS.', 'A digital library of iconic Japanese stories and poems.', 'Ichido wa Yon de Okitai on NDS is a portable library. Read works from authors like Soseki Natsume and Ryunosuke Akutagawa, featuring adjustable text sizes and a built-in dictionary for an immersive reading experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ico-soccer-europe-enfrdeesit', 'NDS', 'Ico Soccer (Europe) (En,Fr,De,Es,It)', '2004', 'Sports', 'IncaGold', '4', 'Arcade', 'Sports simulation.', 'Manage your soccer team and win international matches.', 'A fast-paced arcade soccer management and action game.', 'Ico Soccer on NDS features a unique "finger-based" control system. Use the stylus to pass, shoot, and direct your players on the field while managing tactics in this accessible and fun sports simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('idaten-jump-ds---moero!-flame-kaiser-japan', 'NDS', 'Idaten Jump DS - Moero! Flame Kaiser (Japan)', '2006', 'Racing', 'Konami', '1', 'Anime', 'Racing and action.', 'Win high-speed mountain bike races and defeat rivals.', 'An intense biking game based on the Idaten Jump anime.', 'Idaten Jump DS: Moero! Flame Kaiser on NDS lets you customize your MTB. Use special "Idaten" moves to overcome obstacles and win races across diverse tracks in this high-energy sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('idol-janshi-suchie-pai-iii-remix-japan', 'NDS', 'Idol Janshi Suchie-Pai III Remix (Japan)', '2007', 'Boardgame', 'Jaleco', '1', 'Mahjong', 'Mahjong and visual novel.', 'Win Mahjong matches and progress through the story.', 'A quirky Mahjong game with anime characters and magic.', 'Idol Janshi Suchie-Pai III Remix on NDS combines traditional Japanese Mahjong with special powers. Defeat opponents in the story mode to unlock galleries and new abilities in this eccentric cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('idolm@ster-the---dearly-stars-japan-ndsi-enhanced', 'NDS', 'Idolm@ster, The - Dearly Stars (Japan) (NDSi Enhanced)', '2009', 'Simulation', 'NamcoBandai', '1', 'Idol', 'Idol simulation and adventure.', 'Manage the careers of three aspiring idols at 876 Production.', 'A deep idol management sim with NDSi camera features.', 'The Idolm@ster: Dearly Stars features a branching narrative. Train your idols in singing and dancing, interact with fans, and use the DSi camera for specialized QR code events in this popular Japanese franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('igor---the-game-europe-enfrdeesit', 'NDS', 'Igor - The Game (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'PyroStudios', '1', 'Movie', 'Action-puzzle and adventure.', 'Help Igor win the Evil Science Fair and save the kingdom.', 'A puzzle-filled adventure based on the animated movie.', 'Igor: The Game on NDS features a mix of combat and environmental puzzles. Play as Igor, Eva, and the other experiments to overcome obstacles and stop the evil Dr. Schadenfreude in this dark and funny quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('igor---the-game-usa', 'NDS', 'Igor - The Game (USA)', '2008', 'Adventure', 'PyroStudios', '1', 'Movie', 'Action-puzzle and adventure.', 'Help Igor win the Evil Science Fair and save the kingdom.', 'A puzzle-filled adventure based on the animated movie.', 'Igor: The Game on NDS features a mix of combat and environmental puzzles. Play as Igor, Eva, and the other experiments to overcome obstacles and stop the evil Dr. Schadenfreude in this dark and funny quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ikamono-tantei---ikatan-japan', 'NDS', 'Ikamono Tantei - Ikatan (Japan)', '2009', 'Adventure', 'Success', '1', 'Mystery', 'Visual novel and investigation.', 'Solve bizarre and "fake" crimes using your detective skills.', 'A humorous and surreal detective adventure from Japan.', 'Ikamono Tantei (Ikatan) on NDS tasks you with solving the weirdest cases imaginable. Interview eccentric suspects and find odd clues to uncover the truth in this stylish and funny narrative game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ikou---intelligenztrainer-fuer-kids-germany', 'NDS', 'IKOU - Intelligenztrainer fuer Kids (Germany)', '2008', 'Educational', 'Tivola', '1', 'Training', 'Educational and brain training.', 'Improve your IQ and cognitive skills through daily drills.', 'A comprehensive intelligence trainer for German kids.', 'IKOU: Intelligenztrainer fuer Kids on NDS offers a variety of mental exercises. Focus on logic, memory, and concentration with structured programs designed to help students sharpen their minds while having fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('il-2-sturmovik---birds-of-prey-europe-enfrdeesit', 'NDS', 'IL-2 Sturmovik - Birds of Prey (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', '1CCompany', '1', 'Flight', 'Flight simulation and combat.', 'Engage in historic WWII aerial battles and complete missions.', 'A realistic and intense air-combat simulator for NDS.', 'IL-2 Sturmovik: Birds of Prey on NDS features iconic aircraft and historic battles. Master flight controls, dogfight against enemy planes, and complete strategic bombing runs in this impressive portable flight sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('il-2-sturmovik---birds-of-prey-usa-enfrdeesit', 'NDS', 'IL-2 Sturmovik - Birds of Prey (USA) (En,Fr,De,Es,It)', '2009', 'Simulation', '1CCompany', '1', 'Flight', 'Flight simulation and combat.', 'Engage in historic WWII aerial battles and complete missions.', 'A realistic and intense air-combat simulator for NDS.', 'IL-2 Sturmovik: Birds of Prey on NDS features iconic aircraft and historic battles. Master flight controls, dogfight against enemy planes, and complete strategic bombing runs in this impressive portable flight sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('illu-logi-vow-japan', 'NDS', 'Illu-Logi VOW (Japan)', '2009', 'Puzzle', 'HudsonSoft', '1', 'Logic', 'Logic puzzle.', 'Solve Nonogram puzzles to reveal hidden pictures.', 'A classic and challenging picture-logic puzzle game.', 'Illu-Logi VOW on NDS offers hundreds of grid-based logic puzzles. Use the stylus to fill in cells based on numerical clues and reveal beautiful pixel-art illustrations in this relaxing Japanese brain-teaser.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('illumislight---hikari-no-puzzle-japan', 'NDS', 'Illumislight - Hikari no Puzzle (Japan)', '2007', 'Puzzle', 'Taito', '1', 'Abstract', 'Puzzle.', 'Manipulate light and mirrors to illuminate the goal.', 'A clever and atmospheric physics-based puzzle game.', 'Illumislight: Hikari no Puzzle tasks you with directing beams of light through complex levels. Use mirrors, prisms, and switches to solve increasingly difficult challenges in this visually soothing NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('illust-logic-ds-+-colorful-logic-japan', 'NDS', 'Illust Logic DS + Colorful Logic (Japan)', '2008', 'Puzzle', 'HudsonSoft', '1', 'Logic', 'Logic puzzle.', 'Solve both black-and-white and color Nonograms.', 'An expanded collection of picture-logic puzzles.', 'Illust Logic DS + Colorful Logic brings the best of Nonograms to NDS. Challenge yourself with multi-colored puzzles that add a new layer of strategy to the classic grid-solving gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('imagine---animal-doctor-usa-enfres', 'NDS', 'Imagine - Animal Doctor (USA) (En,Fr,Es)', '2009', 'Simulation', 'Altron', '1', 'Medical', 'Simulation.', 'Care for sick animals and manage your own clinic.', 'A heartwarming veterinary simulation for animal lovers.', 'Imagine: Animal Doctor on NDS lets you treat everything from puppies to exotic animals. Diagnose illnesses, perform check-ups, and nurse your patients back to health to become the best vet in town.');
