INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('imagine---babies-europe-enfrdeesitnl', 'NDS', 'Imagine - Babies (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Simulation', 'MagicPockets', '1', 'Casual', 'Baby care simulation.', 'Take care of adorable babies and keep them happy.', 'A sweet and realistic babysitting simulation.', 'Imagine: Babies on NDS lets you experience the joys of childcare. Feed, bathe, and play with virtual infants, managing their needs and moods to prove you are a top-tier babysitter.');
