INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-athletics-europe-enfrdeesit', 'NDS', 'International Athletics (Europe) (En,Fr,De,Es,It)', '2007', 'Sports', '49Games', '1', 'Athletics', 'Sports simulation.', 'Compete in various track and field events for the gold.', 'A realistic and challenging athletics simulator.', 'International Athletics on NDS features 11 different events, from the 100m sprint to the javelin throw. Use precise touch-screen timing to beat world records and win the decathlon.');
