INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('inuyasha---secret-of-the-divine-jewel-usa', 'NDS', 'InuYasha - Secret of the Divine Jewel (USA)', '2007', 'RolePlaying', 'Art Co. Ltd.', '1', 'ActionRPG', 'Turn-based RPG.', 'Help Inuyasha and his friends recover the Sagemore fragments.', 'A deep RPG based on the iconic anime and manga series.', 'InuYasha: Secret of the Divine Jewel features an original storyline. Command Inuyasha, Kagome, and new allies in tactical turn-based battles while exploring the feudal era of Japan.');
