INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('isanghan-naraui-princess-korea', 'NDS', 'Isanghan Naraui Princess (Korea)', '2009', 'Adventure', 'Sonnet', '1', 'VisualNovel', 'Adventure and social.', 'Explore a magical kingdom and fulfill your royal duties.', 'A charming Korean adventure for young players.', 'Isanghan Naraui Princess (Princess in Wonderland) features mini-games and social interactions. Customize your princess and explore a vibrant world filled with fantasy and fun on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ishin-no-arashi---shippuu-ryouma-den-japan', 'NDS', 'Ishin no Arashi - Shippuu Ryouma Den (Japan)', '2008', 'Strategy', 'FromSoftware', '1', 'Historical', 'Strategy and historical.', 'Change the course of Japanese history during the Bakumatsu.', 'A deep historical strategy and simulation game.', 'Ishin no Arashi on NDS lets you play as famous historical figures like Ryoma Sakamoto. Influence the nation through diplomacy, combat, and political strategy in this detailed epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('isola-dei-famosi-l-italy', 'NDS', 'Isola dei Famosi, L'' (Italy)', '2008', 'Reality', 'Magnussoft', '1', 'RealityShow', 'Survival mini-games.', 'Survive the island and win the reality show competition.', 'A mini-game collection based on the Italian "Celebrity Survivor."', 'L''Isola dei Famosi on NDS lets you manage your hunger, popularity, and stamina. Compete in trials and interact with other contestants to avoid being voted off the island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('its-tehodoki!-hannya-shingyou-nyuumon-japan', 'NDS', 'It''s Tehodoki! Hannya Shingyou Nyuumon (Japan)', '2009', 'Education', 'ASK', '1', 'Buddhism', 'Spiritual and educational.', 'Learn the Heart Sutra and practice Buddhist meditation.', 'A peaceful guide to Buddhist teachings and chanting.', 'Hannya Shingyou Nyuumon on NDS provides a digital way to learn sacred texts. Practice calligraphy with the stylus and learn the meanings behind the sutras in this tranquil experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('item-getter---bokura-no-kagaku-to-mahou-no-kankei-japan', 'NDS', 'Item Getter - Bokura no Kagaku to Mahou no Kankei (Japan)', '2009', 'Adventure', 'Jupiter', '1', 'Adventure', 'RPG and collection.', 'Collect over 1,000 items through science and magic.', 'A deep item-collecting RPG with crafting mechanics.', 'Item Getter on NDS focuses on the joy of discovery. Explore a vast world, combine elements to create new items, and complete quests in this creative and charming Japanese adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itouke-no-urawaza-ds-japan', 'NDS', 'Itouke no Urawaza DS (Japan)', '2008', 'Simulation', 'Nintendo', '1', 'LifeHacks', 'Lifestyle and tips.', 'Learn life hacks and "Urawaza" to make daily life easier.', 'A digital guide to Japanese household tips and tricks.', 'Itouke no Urawaza DS provides hundreds of clever solutions for common problems. From cleaning hacks to cooking shortcuts, this interactive guide is based on a popular Japanese TV show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itsudemo-dokodemo---onita-atsushi-no-seiji-quiz-ds-japan', 'NDS', 'Itsudemo Dokodemo - Onita Atsushi no Seiji Quiz DS (Japan)', '2009', 'Education', 'Nintendo', '1', 'Quiz', 'Educational and trivia.', 'Learn about Japanese politics through quizzes and mini-games.', 'A unique political education game featuring Atsushi Onita.', 'Seiji Quiz DS makes learning about government engaging. Answer questions on law, history, and current events to build your political knowledge on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itsudemo-dokodemo-dekiru-igo---ai-igo-ds-japan', 'NDS', 'Itsudemo Dokodemo Dekiru Igo - AI Igo DS (Japan)', '2007', 'BoardGame', 'Nintendo', '1', 'BoardGame', 'Board game.', 'Master the game of Go against a sophisticated AI.', 'A portable and high-level Go (Igo) simulation.', 'AI Igo DS offers several difficulty levels for players of all skill sets. Practice strategies, analyze your moves, and enjoy a professional Go experience on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itsudemo-dokodemo-dekiru-shougi---ai-shougi-ds-japan', 'NDS', 'Itsudemo Dokodemo Dekiru Shougi - AI Shougi DS (Japan)', '2007', 'BoardGame', 'Nintendo', '1', 'BoardGame', 'Board game.', 'Master the game of Shogi against a sophisticated AI.', 'A portable and high-level Shogi (Japanese Chess) sim.', 'AI Shougi DS provides a challenging and authentic Shogi experience. Learn the rules or sharpen your tactics against an AI that adapts to your playing style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itsumo-no-shokuzai-de-dekichau-suteki-na-sweets-to-gochisou-japan', 'NDS', 'Itsumo no Shokuzai de Dekichau Suteki na Sweets to Gochisou. (Japan)', '2009', 'Simulation', 'Nintendo', '1', 'Cooking', 'Cooking simulation.', 'Create wonderful sweets and meals using everyday ingredients.', 'A practical Japanese dessert and cooking guide for NDS.', 'Itsumo no Shokuzai features a wide variety of recipes for sweets and main dishes. Follow interactive, step-by-step instructions to turn common household ingredients into professional-looking treats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itsuwari-no-rondo-japan', 'NDS', 'Itsuwari no Rondo (Japan)', '2008', 'Adventure', 'Nippon Ichi Software', '1', 'VisualNovel', 'Tactical RPG.', 'Lead Prince Serdic and his army to reclaim his lost kingdom.', 'A deep and challenging grid-based tactical RPG.', 'Itsuwari no Rondo (Rondo of Swords) features a unique "Route Maneuver" combat system. Draw paths through enemies to attack and reposition your units in this complex fantasy epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ivy-the-kiwi---tsuta-ga-michibiku-monogatari-japan', 'NDS', 'Ivy the Kiwi - Tsuta ga Michibiku Monogatari. (Japan)', '2010', 'Platform', 'Prope', '1', 'ActionPlatformer', 'Action-platformer.', 'Guide Ivy the Kiwi to find her mother using vines.', 'A beautiful and unique hand-drawn action game.', 'Ivy the Kiwi on NDS uses the stylus to draw vines that fling and guide Ivy through levels. Experience a charming story with a "storybook" art style and creative environmental puzzles.');
