INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('izuna---legend-of-the-unemployed-ninja-usa', 'NDS', 'Izuna - Legend of the Unemployed Ninja (USA)', '2007', 'RolePlaying', 'Natsume', '1', 'RoguelikeRPG', 'Roguelike RPG.', 'Explore procedurally generated dungeons and find loot.', 'A humorous and tough dungeon-crawling RPG.', 'Izuna: Legend of the Unemployed Ninja on NDS features classic roguelike mechanics. Help the spunky Izuna clear dungeons, manage your equipment, and defeat bosses in this charmingly difficult quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('izuna---the-legend-of-the-ninja-europe-enfrit', 'NDS', 'Izuna - The Legend of the Ninja (Europe) (En,Fr,It)', '2007', 'RolePlaying', 'Natsume', '1', 'RoguelikeRPG', 'Roguelike RPG.', 'Explore procedurally generated dungeons and find loot.', 'A humorous and tough dungeon-crawling RPG.', 'Izuna: Legend of the Unemployed Ninja on NDS features classic roguelike mechanics. Help the spunky Izuna clear dungeons, manage your equipment, and defeat bosses in this charmingly difficult quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('izuna-2---the-unemployed-ninja-returns-usa', 'NDS', 'Izuna 2 - The Unemployed Ninja Returns (USA)', '2008', 'RolePlaying', 'Natsume', '1', 'RoguelikeRPG', 'Roguelike RPG.', 'Find Shino''s sister while exploring dangerous dungeons.', 'The expanded and refined sequel to the Izuna saga.', 'Izuna 2: The Unemployed Ninja Returns introduces a "Tag Team" system. Switch between characters in real-time as you navigate challenging floors and enjoy the series'' signature humor and difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('japprends-langlais-cp-cm1-europe-frit', 'NDS', 'J''Apprends l''Anglais CP-CM1 (Europe) (Fr,It)', '2008', 'Education', 'Mindscape', '1', 'LanguageLearning', 'Educational and language.', 'Learn English vocabulary and grammar for primary school.', 'A fun English language trainer for French speakers.', 'J''Apprends l''Anglais on NDS makes learning a second language engaging. Through mini-games and interactive lessons, students from CP to CM1 can build a solid foundation in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('j4g---a-girls-world-europe-ende', 'NDS', 'J4G - A Girl''s World (Europe) (En,De)', '2009', 'Simulation', '505 Games', '1', 'LifeSimulation', 'Social simulation.', 'Navigate the social life and fashion world of a teenage girl.', 'A lifestyle and mini-game collection for young girls.', 'J4G - A Girl''s World on NDS lets you customize your avatar, play fashion-based mini-games, and manage your social calendar in a fun, safe digital environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jackass---the-game-ds-europe-enfrdeesit', 'NDS', 'Jackass - The Game DS (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Sidhe Interactive', '4', 'ActionAdventure', 'Mini-game collection.', 'Complete painful and hilarious stunts to score points.', 'A wacky stunt-filled game based on the MTV show.', 'Jackass: The Game DS features dozens of masochistic mini-games. From shopping cart racing to rooftop jumps, use the touch screen to perform the crew''s most infamous and ridiculous stunts.');
