INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jacqueline-wilsons-tracy-beaker---the-game-europe', 'NDS', 'Jacqueline Wilson''s Tracy Beaker - The Game (Europe)', '2009', 'Adventure', 'Nintendo', '1', 'StoryAdventure', 'Adventure and social.', 'Help Tracy navigate life at "The Dumping Ground."', 'A story-driven adventure based on the popular book series.', 'Tracy Beaker: The Game on NDS lets you play as the iconic character. Participate in mini-games, build friendships, and help Tracy through her daily challenges in this heartwarming adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jagged-alliance-usa', 'NDS', 'Jagged Alliance (USA)', '2009', 'Strategy', 'Sir-Tech', '1', 'TacticalStrategy', 'Tactical RPG.', 'Recruit mercenaries and take back the island of Metavira.', 'A deep and strategic turn-based combat game.', 'Jagged Alliance on NDS brings the PC strategy classic to the handheld. Manage your budget, hire unique mercenaries, and use tactical positioning to win skirmishes in this intense military sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jaka-jaka-music!-m09-japan', 'NDS', 'Jaka Jaka Music! M09 (Japan)', '2009', 'Music', 'Nintendo', '1', 'RhythmGame', 'Music simulation.', 'Play a digital guitar and create your own songs.', 'A portable guitar simulator with a musical touch.', 'Jaka Jaka Music! turns your NDS into a musical instrument. Strum the touch screen and use buttons to change chords, allowing you to practice songs or compose your own tracks on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jake-hunter---detective-chronicles-usa', 'NDS', 'Jake Hunter - Detective Chronicles (USA)', '2009', 'Adventure', 'Aksys Games', '1', 'Detective', 'Visual novel and mystery.', 'Solve three complex cases as hard-boiled detective Jake Hunter.', 'A classic noir-style investigation game.', 'Jake Hunter: Detective Chronicles features a unique atmosphere and gritty stories. Search for clues, interview witnesses, and use your logic to solve crimes in this stylish narrative adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jake-hunter-detective-story---memories-of-the-past-usa', 'NDS', 'Jake Hunter Detective Story - Memories of the Past (USA)', '2009', 'Adventure', 'Aksys Games', '1', 'Detective', 'Visual novel and mystery.', 'Solve deep mysteries and uncover the detective''s past.', 'An expanded collection of Jake Hunter mysteries.', 'Memories of the Past on NDS includes several classic cases and new scenarios. Experience the life of a private investigator through atmospheric storytelling and challenging puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jake-power---firefighter-australia-enfres', 'NDS', 'Jake Power - Firefighter (Australia) (En,Fr,Es)', '2009', 'Simulation', 'Mindscape', '1', 'JobSimulation', 'Simulation.', 'Respond to emergencies and save citizens from fires.', 'A hero-themed simulation about life as a firefighter.', 'Jake Power: Firefighter on NDS lets you drive the fire truck and put out blazes. Rescue people from burning buildings and learn about fire safety in this action-packed career sim.');
