INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jambo!-safari---animal-rescue-europe-enfrdeit', 'NDS', 'Jambo! Safari - Animal Rescue (Europe) (En,Fr,De,It)', '2009', 'Simulation', 'Sega', '1', 'AnimalRescue', 'Adventure and simulation.', 'Drive across the savanna and rescue injured animals.', 'A wild animal rescue adventure based on the Sega arcade.', 'Jambo! Safari on NDS takes you to the African plains. Use your custom vehicle to track down animals, treat them at the clinic, and learn about wildlife conservation.');
