INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-patterson-womens-murder-club---games-of-passion-europe-enfrdeesit-ndsi-enhanced', 'NDS', 'James Patterson Women''s Murder Club - Games of Passion (Europe) (En,Fr,De,Es,It) (NDSi Enhanced)', '2009', 'Adventure', 'Griptonite Games', '1', 'Detective', 'Hidden object and mystery.', 'Solve a series of murders through investigation and puzzles.', 'A DSi-enhanced detective game based on the hit novels.', 'Women''s Murder Club: Games of Passion on NDS tasks you with finding clues and analyzing evidence. Use the DSi camera for unique mini-games and solve complex cases in this thrilling James Patterson adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-pond---codename-robocod-europe-enfrdeesit', 'NDS', 'James Pond - Codename Robocod (Europe) (En,Fr,De,Es,It)', '1992', 'Platform', 'Millennium Interactive', '1', 'Platformer', '2D Platformer.', 'Rescue stolen penguins across various toy-themed levels.', 'A classic retro revival of the iconic aquatic hero.', 'James Pond: Codename Robocod on NDS brings the stretchable agent back. Navigate surreal worlds, defeat wacky bosses, and use your robotic suit to scale walls in this faithful and fun 16-bit remake.');
