INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jigapix---pets-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Jigapix - Pets (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Puzzle', 'Creat Studios', '1', 'Jigsaw', 'Jigsaw Puzzle.', 'Assemble cute pet puzzles using the touch screen.', 'A DSi-enhanced puzzle game for animal lovers.', 'Jigapix: Pets on NDS lets you solve puzzles of puppies, kittens, and more. Use the DSi camera to create your own custom puzzles from real-world photos of your pets!');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jigapix---wild-world-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Jigapix - Wild World (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Puzzle', 'Creat Studios', '1', 'Jigsaw', 'Jigsaw Puzzle.', 'Assemble beautiful wildlife puzzles on your DS.', 'A DSi-enhanced puzzle game featuring wild animals.', 'Jigapix: Wild World brings nature to your screen. Solve puzzles of lions and bears, or use the NDSi camera to snap a photo and turn it into a challenging jigsaw instantly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jigapix---wonderful-world-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Jigapix - Wonderful World (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Puzzle', 'Creat Studios', '1', 'Jigsaw', 'Jigsaw Puzzle.', 'Assemble famous world landmark puzzles.', 'A DSi-enhanced puzzle game for world travelers.', 'Jigapix: Wonderful World features iconic locations from around the globe. Solve beautiful jigsaws or create your own using the DSi''s built-in camera and photo gallery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jigoku-shoujo---akekazura-japan', 'NDS', 'Jigoku Shoujo - Akekazura (Japan)', '2007', 'Adventure', 'Compile Heart', '1', 'VisualNovel', 'Adventure / Mystery.', 'Solve dark mysteries as the Hell Girl, Ai Enma.', 'A psychological mystery game based on the anime.', 'Jigoku Shoujo: Akekazura on NDS features an original story. Interact with characters, gather evidence, and decide who will be sent to hell in this atmospheric and dark narrative adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jigsaw-puzzle-ds---ds-de-meguru-sekai-isan-no-tabi-japan', 'NDS', 'Jigsaw Puzzle DS - DS de Meguru Sekai Isan no Tabi (Japan)', '2008', 'Puzzle', 'Nintendo', '1', 'Jigsaw', 'Jigsaw Puzzle.', 'Complete puzzles of World Heritage sites.', 'A relaxing tour of the world through jigsaw puzzles.', 'Jigsaw Puzzle DS takes you to famous landmarks. Solve puzzles of the Great Wall, the Eiffel Tower, and more while learning historical facts in this educational Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jigsaw-world---daigekitou!-jig-battle-heroes-japan', 'NDS', 'Jigsaw World - Daigekitou! Jig Battle Heroes (Japan)', '2009', 'Action', 'Racjin', '2', 'ArcadeBattle', 'Puzzle / Battle.', 'Defeat rivals in fast-paced jigsaw puzzle battles.', 'A competitive and heroic take on jigsaw puzzles.', 'Jigsaw World: Jig Battle Heroes turns puzzles into combat. Solve pieces faster than your opponent to launch attacks and become the ultimate puzzle champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jiji-tsuushin-shuppan-kyoku-kyouryoku---katei-no-igaku---ds-de-kitaeru-shokuzai-kenkou-training-japan', 'NDS', 'Jiji Tsuushin Shuppan-Kyoku Kyouryoku - Katei no Igaku - DS de Kitaeru Shokuzai Kenkou Training (Japan)', '2009', 'Education', 'Jiji Press', '1', 'HealthTraining', 'Educational / Health.', 'Train your health knowledge and learn about nutrition.', 'A wellness and medical training guide for families.', 'Katei no Igaku on NDS provides medical advice and health quizzes. Learn about ingredients, symptoms, and healthy habits through structured daily training sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jillian-michaels-fitness-ultimatum-2010-usa', 'NDS', 'Jillian Michaels Fitness Ultimatum 2010 (USA)', '2010', 'Fitness', 'Griptonite Games', '1', 'FitnessTraining', 'Fitness / Exercise.', 'Complete Jillian Michaels'' workout programs to get fit.', 'A portable personal trainer and workout guide.', 'Jillian Michaels Fitness Ultimatum 2010 on NDS features customized routines. Track your progress, follow exercise animations, and stay motivated with Jillian’s signature coaching style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jin-samguk-mussang-ds---fighters-battle-korea', 'NDS', 'Jin Samguk Mussang DS - Fighter''s Battle (Korea)', '2008', 'Action', 'Koei', '2', 'HackAndSlash', 'Strategy / Battle.', 'Fight through ancient China using the power of cards.', 'A Korean version of the tactical Dynasty Warriors spin-off.', 'Jin Samguk Mussang DS features grid-based battles. Collect character cards, build a powerful deck, and conquer territories in this unique strategic take on the Warriors franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jinsei-game-japan', 'NDS', 'Jinsei Game (Japan)', '2003', 'BoardGame', 'Takara', '4', 'LifeSimulation', 'Board Game.', 'Navigate through life''s stages and retire wealthy.', 'A digital version of the iconic "The Game of Life."', 'Jinsei Game on NDS lets you go to college, get married, and start a career. Spin the wheel and see where life takes you in this classic Japanese board game simulation.');
