INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jinsei-game-q---ds-heisei-no-dekigoto-japan', 'NDS', 'Jinsei Game Q - DS Heisei no Dekigoto (Japan)', '2008', 'BoardGame', 'Takara', '4', 'LifeSimulation', 'Board Game / Quiz.', 'Experience the events of the Heisei era through a board game.', 'A historical and nostalgic life-sim board game.', 'Jinsei Game Q - Heisei features real events from modern Japanese history. Play through the era while answering trivia questions and building your virtual life.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jinsei-game-q---ds-shouwa-no-dekigoto-japan', 'NDS', 'Jinsei Game Q - DS Shouwa no Dekigoto (Japan)', '2008', 'BoardGame', 'Takara', '4', 'LifeSimulation', 'Board Game / Quiz.', 'Experience the events of the Shouwa era through a board game.', 'A nostalgic look at mid-century Japan via a board game.', 'Jinsei Game Q - Shouwa takes players back in time. Relive the landmarks of the Shouwa era through trivia and classic life-sim gameplay on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jishin-ds-72-jikan-japan', 'NDS', 'Jishin DS 72-jikan (Japan)', '2008', 'Education', 'Nintendo', '1', 'DisasterAwareness', 'Educational / Survival.', 'Learn how to survive the first 72 hours after a disaster.', 'A vital earthquake survival and preparation guide.', 'Jishin DS 72-jikan teaches you what to do during an earthquake. Learn emergency procedures, first aid, and survival tips in this unique and educational Japanese simulation.');
