INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jjangguneun-monmallyeo---cinemaland-chalkak-chalkak-daesodong!-korea', 'NDS', 'Jjangguneun Monmallyeo - Cinemaland Chalkak Chalkak Daesodong! (Korea)', '2009', 'Education', 'Unknown', '1', 'KidsMiniGames', 'Action-adventure.', 'Help Shin-chan through movie-themed platforming levels.', 'A fun Korean platformer based on the Crayon Shin-chan films.', 'Jjangguneun Monmallyeo - Cinemaland features diverse mini-games and platforming stages. Use Shin-chan''s wacky costumes and abilities to clear levels inspired by his most famous movies.');
