INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juggler-ds-japan', 'NDS', 'Juggler DS (Japan)', '2007', 'Gambling', 'Success', '1', 'PachislotSimulation', 'Casino simulation.', 'Play the Juggler series of Japanese slot machines.', 'A comprehensive Pachi-Slot simulator for NDS.', 'Juggler DS features multiple machines from the iconic series. Learn the mechanics and test your luck in this authentic recreation of Japanese arcade slot gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juiced-2---hot-import-nights-europe-enfrdeesit', 'NDS', 'Juiced 2 - Hot Import Nights (Europe) (En,Fr,De,Es,It)', '2007', 'Racing', 'Juice Games', '1', 'StreetRacing', 'Racing simulation.', 'Customize your car and win the Hot Import Nights events.', 'A high-octane street racing and tuning game.', 'Juiced 2 on NDS lets you customize every part of your ride. Compete in drift events and high-speed races across world-famous tracks to become the king of the import scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juiced-2---hot-import-nights-usa', 'NDS', 'Juiced 2 - Hot Import Nights (USA)', '2007', 'Racing', 'Juice Games', '1', 'StreetRacing', 'Racing simulation.', 'Customize your car and win the Hot Import Nights events.', 'A high-octane street racing and tuning game.', 'Juiced 2 on NDS lets you customize every part of your ride. Compete in drift events and high-speed races across world-famous tracks to become the king of the import scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jumble-madness-usa', 'NDS', 'Jumble Madness (USA)', '2009', 'Puzzle', 'Konami', '1', 'WordPuzzle', 'Puzzle and word game.', 'Solve scrambled word puzzles and logic riddles.', 'A massive collection of Jumble word puzzles.', 'Jumble Madness on NDS features hundreds of brain-teasing word scrambles. Use the stylus to rearrange letters and solve the daily Jumble challenges in this addictive word game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jump-super-stars-japan', 'NDS', 'Jump Super Stars (Japan)', '2005', 'Action', 'Ganbarion', '4', 'AnimeFighting', 'Fighting and action.', 'Battle with characters from the Shonen Jump universe.', 'A legendary crossover fighter for anime fans.', 'Jump Super Stars on NDS features iconic heroes like Goku, Naruto, and Luffy. Build your "Koma" deck to call in strikers and battle in dynamic 2D arenas in this Japanese masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jump-ultimate-stars-english', 'NDS', 'Jump Ultimate Stars (English)', '2006', 'Action', 'Ganbarion', '4', 'AnimeFighting', 'Fighting and action.', 'Battle with characters from the Shonen Jump universe.', 'The definitive crossover fighting game with an English patch.', 'Jump Ultimate Stars (English) brings the massive roster of 300+ characters to English speakers. Engage in epic 4-player battles and use strategic manga-panel layouts to win.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jump-ultimate-stars-japan', 'NDS', 'Jump Ultimate Stars (Japan)', '2006', 'Action', 'Ganbarion', '4', 'AnimeFighting', 'Fighting and action.', 'Battle with characters from the Shonen Jump universe.', 'The expanded sequel to the hit anime crossover fighter.', 'Jump Ultimate Stars features more characters, improved mechanics, and online play. Create the ultimate anime dream team and battle across diverse manga-themed stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-school-europe-enfrdeesitnl', 'NDS', 'Jungle School (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Education', 'Tivola', '1', 'EducationalAdventure', 'Management simulation.', 'Manage a school for animals and keep them happy.', 'A cute animal care and education sim.', 'Jungle School on NDS tasks you with teaching young animals. Manage classrooms, schedule activities, and ensure every animal student thrives in this charming and colorful simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('junior-brain-trainer---maths-edition-europe', 'NDS', 'Junior Brain Trainer - Maths Edition (Europe)', '2009', 'Education', 'Oxygen Games', '1', 'MathTraining', 'Educational and Math.', 'Solve fun arithmetic puzzles to improve math skills.', 'A targeted math trainer for primary school children.', 'Junior Brain Trainer: Maths Edition on NDS makes numbers fun. With various difficulty levels, it helps kids master addition, subtraction, and logic through engaging daily mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('junior-brain-trainer-europe-enfrdeesit', 'NDS', 'Junior Brain Trainer (Europe) (En,Fr,De,Es,It)', '2008', 'Education', 'Oxygen Games', '1', 'BrainTraining', 'Educational and Brain Training.', 'Complete daily mental exercises to boost cognitive skills.', 'A comprehensive brain trainer designed for kids.', 'Junior Brain Trainer for NDS offers a variety of puzzles including reading, spelling, and logic. Designed for young minds, it tracks progress and rewards daily learning with fun unlockables.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('junior-brain-trainer-2-europe-enfrdeesit', 'NDS', 'Junior Brain Trainer 2 (Europe) (En,Fr,De,Es,It)', '2009', 'Education', 'Oxygen Games', '1', 'BrainTraining', 'Educational and Brain Training.', 'Advance your mental skills with new and tougher puzzles.', 'The expanded sequel to the popular kids'' brain trainer.', 'Junior Brain Trainer 2 on NDS features more complex challenges in memory, math, and observation. It’s the perfect tool for students to keep their minds sharp while having fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('junior-classic-books-europe', 'NDS', 'Junior Classic Books (Europe)', '2008', 'Education', 'Games Factory Online', '1', 'InteractiveStorybook', 'Digital Literature.', 'Read and interact with famous classic stories.', 'A portable library of timeless tales for young readers.', 'Junior Classic Books on NDS brings stories like Alice in Wonderland to life. Features easy-to-read text, professional narration, and interactive illustrations to encourage a love for reading.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('junior-classic-games-europe-enfrdeesit', 'NDS', 'Junior Classic Games (Europe) (En,Fr,De,Es,It)', '2008', 'Miscellaneous', 'Games Factory Online', '1', 'MiniGameCollection', 'Puzzle and Board Games.', 'Master a collection of classic childhood games.', 'A variety pack of traditional games for the NDS.', 'Junior Classic Games includes favorites like Chess, Checkers, and Snakes & Ladders. Use the touch screen to play against friends or AI in this versatile digital toy box.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('junior-classic-games-usa-enfrdeesit', 'NDS', 'Junior Classic Games (USA) (En,Fr,De,Es,It)', '2008', 'Miscellaneous', 'Games Factory Online', '1', 'MiniGameCollection', 'Puzzle and Board Games.', 'Master a collection of classic childhood games.', 'A variety pack of traditional games for the NDS.', 'Junior Classic Games includes favorites like Chess, Checkers, and Snakes & Ladders. Use the touch screen to play against friends or AI in this versatile digital toy box.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('junior-wort-quiz-das-germany', 'NDS', 'Junior Wort-Quiz, Das (Germany)', '2009', 'Education', 'Tivola', '1', 'WordQuiz', 'Educational and Word Game.', 'Solve word puzzles to build a German vocabulary.', 'A fun German language and spelling trainer for kids.', 'Das Junior Wort-Quiz on NDS challenges kids with spelling bees and word associations. It’s a great educational tool for improving German literacy through interactive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('just-in-time-translations---say-it-in-6-languages-usa', 'NDS', 'Just in Time Translations - Say It in 6 Languages (USA)', '2007', 'Education', 'Around the World', '1', 'LanguageLearning', 'Educational and Language.', 'Learn and translate phrases in 6 different languages.', 'A portable multi-language translator and tutor.', 'Just in Time Translations on NDS lets you learn English, French, German, Spanish, Italian, and Mandarin. Features voice samples and quizzes for quick real-world communication.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('just-sing!-europe-enfrdenl-ndsi-enhanced', 'NDS', 'Just Sing! (Europe) (En,Fr,De,Nl) (NDSi Enhanced)', '2011', 'Music', 'Tivola', '1', 'KaraokeRhythm', 'Music and Karaoke.', 'Sing along to pop hits and record your performances.', 'A DSi-enhanced karaoke experience for aspiring stars.', 'Just Sing! on NDS uses the microphone to score your singing talent. Features a great playlist of hits and uses the DSi camera for fun visual effects while you perform.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('justice-league-heroes-europe-enfrdeesit', 'NDS', 'Justice League Heroes (Europe) (En,Fr,De,Es,It)', '2006', 'Action', 'Snowblind Studios', '1', 'SuperheroAction', 'Action-adventure.', 'Save Earth from Brainiac and Darkseid with the Justice League.', 'An epic superhero brawler featuring DC''s finest.', 'Justice League Heroes on NDS lets you control Batman, Superman, Wonder Woman, and more. Use unique superpowers and strategic combat to defeat classic villains in this intense adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('justice-league-heroes-usa', 'NDS', 'Justice League Heroes (USA)', '2006', 'Action', 'Snowblind Studios', '1', 'SuperheroAction', 'Action-adventure.', 'Save Earth from Brainiac and Darkseid with the Justice League.', 'An epic superhero brawler featuring DC''s finest.', 'Justice League Heroes on NDS lets you control Batman, Superman, Wonder Woman, and more. Use unique superpowers and strategic combat to defeat classic villains in this intense adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juushin-enbu-ds-japan', 'NDS', 'Juushin Enbu DS (Japan)', '2007', 'Action', 'Dimps', '2', 'AnimeFighting', 'Action-adventure.', 'Fight through ancient China using martial arts and spirits.', 'A stylish action game based on the Juushin Enbu anime.', 'Juushin Enbu DS (Hero Tales) features fast-paced combat and a deep storyline. Control Taito and his allies to master the Seven Stars'' power and restore peace to the Empire.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juushinden---ultimate-beast-battlers-japan', 'NDS', 'Juushinden - Ultimate Beast Battlers (Japan)', '2006', 'Action', 'Spike', '2', 'MonsterBattling', 'Battle and RPG.', 'Collect and battle legendary beasts in an arena.', 'A strategic monster-battling RPG for the NDS.', 'Juushinden: Ultimate Beast Battlers lets you customize your monsters and engage in tactical duels. Use the dual screen to manage your team and unleash devastating special attacks.');